prepareMapZones(FIELD_ZONES);

// 章ごとの区画（先頭が到着地点）
const CHAPTER_ZONES = [
  ['pokapoka', 'hill', 'forest_in', 'forest_deep', 'rat_nest'],
  ['road1', 'road_rest', 'woods', 'road2'],
  ['nyahaha', 'castle', 'castle_in', 'tower', 'tower_2f', 'tower_3f', 'tower_top'],
  ['valley', 'valley_village', 'cave', 'cave_lake', 'cave_deep'],
  ['ruins_out', 'ruins_in'],
  ['demon_land', 'demon_castle', 'demon_castle_2f', 'demon_throne'],
  ['tree_root', 'tree_under'],
  ['world_end'],
  ['dream'],
];
function zoneChapter(id) { return FIELD_ZONES[id].ci; }

// 区画同士の最短経路（任務の目的地が別区画のときの案内用）
function zonePath(from, to) {
  const prev = { [from]: null }, q = [from];
  while (q.length) {
    const z = q.shift(); if (z === to) break;
    for (const e of FIELD_ZONES[z].exits) if (!(e.to in prev) && zoneOpen(e.to)) { prev[e.to] = z; q.push(e.to); }
  }
  if (!(to in prev)) return null;
  const path = []; for (let z = to; z; z = prev[z]) path.unshift(z);
  return path;
}
// after：そのシーンを見終えるまで、区画へのゲートは閉ざされている
function zoneOpen(id) {
  const Z = FIELD_ZONES[id];
  if (!Z) return false;
  return stageUnlocked(Z.stage) && (!Z.after || typeof Story === 'undefined' || Story.seen(Z.after));
}
// 区画の戦場（ワールド座標）。地形マップの区画はマス座標から直す
function zoneArenas(Z) { return (Z.arenas || []).map(([x, z, f]) => { const [wx, wz] = Z.map ? zonePoint(Z, [x, z]) : [x, z]; return { x: wx, z: wz, face: f || 0 }; }); }
// その区画に敵が出るか（calmAfter のステージを越えると静かになる）
function zoneCalm(Z) { return !!(Z.town || (Z.calmAfter && Save.data.cleared[Z.calmAfter])); }
function exitPos(zone, e) {
  const hw = zone.w / 2, hd = zone.d / 2;
  switch (e.side) {
    case 'n': return { x: e.at, z: -hd + 0.5, nx: 0, nz: 1 };
    case 's': return { x: e.at, z: hd - 0.5, nx: 0, nz: -1 };
    case 'e': return { x: hw - 0.5, z: e.at, nx: -1, nz: 0 };
    default: return { x: -hw + 0.5, z: e.at, nx: 1, nz: 0 };
  }
}
// NPC の台詞：物語の進み具合で変わる
function npcLines(n) {
  let lines = n.lines;
  for (const [cond, ...ls] of n.v || []) if (storyCond(cond)) lines = ls;
  return lines;
}
function storyCond(cond) {
  if (!cond) return true;
  const [k, v] = cond.split(':');
  if (k === 'scene') return typeof Story !== 'undefined' && Story.seen(v);
  if (k === 'clear') return !!Save.data.cleared[v];
  if (k === 'flag') return !!(Save.data.flags || {})[v];
  if (k === 'done') return typeof Story !== 'undefined' && Story.done();
  return false;
}

// 世界の果てへのびる樹の根（暗い奈落でも木の根と分かるよう、少しだけ自らほの明るい）
function rootMat(glow = 0) { return new THREE.MeshStandardMaterial({ color: '#8a6a48', emissive: '#6a4a2a', emissiveIntensity: glow, roughness: 0.9 }); }

// ============================================================
//  区画の地形・小物を組み立てるキット
// ============================================================
const ZMAT = {
  metal: ['#5a5a68', 0.6, 0.4], stone: ['#a8a296', 0.02, 0.92], stone2: ['#8a847a', 0.02, 0.92], marble: ['#e2dccf', 0.1, 0.6],
  wood: ['#9a6a42', 0.02, 0.85], wood2: ['#6a4a30', 0.02, 0.88], bark: ['#7a5a3a', 0, 0.95], plaster: ['#fff4e2', 0.02, 0.9], plaster2: ['#f6e4cc', 0.02, 0.9],
  roofRed: ['#e05a4a', 0.05, 0.7], roofBlue: ['#5a8ad8', 0.05, 0.7], roofGreen: ['#6ab85a', 0.05, 0.7], roofOrange: ['#f09a4a', 0.05, 0.7], roofPurple: ['#8a5ad8', 0.05, 0.7], roofGray: ['#8a8a96', 0.05, 0.8],
  leaf: ['#5ab04a', 0, 0.85], leaf2: ['#4a9a3e', 0, 0.85], leafDark: ['#3a6a3a', 0, 0.9], leafGray: ['#8a9480', 0, 0.9], leafPink: ['#ffb8d0', 0, 0.8], leafPurple: ['#7a4a9a', 0, 0.85],
  grass: ['#7ab85a', 0, 0.95], rock: ['#9a9488', 0.02, 0.95], rockDark: ['#4a4450', 0.02, 0.95], dirt: ['#a8845a', 0, 1],
  cloth: ['#5a8ad8', 0, 0.9], clothRed: ['#e05a4a', 0, 0.9], clothYellow: ['#ffd27a', 0, 0.9], clothPink: ['#ff9ac8', 0, 0.9], clothPurple: ['#8a5ad8', 0, 0.9], clothWhite: ['#fff8f0', 0, 0.9],
  gold: ['#e8c060', 0.8, 0.3], iron: ['#3a3a44', 0.7, 0.45], red: ['#d0403a', 0.1, 0.6], white: ['#ffffff', 0, 0.8],
  cheese: ['#ffd24a', 0, 0.7], darkStone: ['#3a3048', 0.1, 0.85], purpleStone: ['#5a4a70', 0.1, 0.8], obsidian: ['#1a1024', 0.6, 0.3],
  candyPink: ['#ffb8d8', 0.05, 0.5], candyBlue: ['#b8e0ff', 0.05, 0.5], candyYellow: ['#fff0a8', 0.05, 0.5], cream: ['#fff8ec', 0, 0.7], choco: ['#7a4a2a', 0.05, 0.6],
};

class ZoneKit {
  constructor(view) {
    this.v = view; this.zone = view.zone; this.scene = view.scene; this.r = view.rand;
    this.T = view.T; this.mc = {}; this.lights = 0;
  }
  gy(x, z) { return this.T ? this.T.baseAt(x, z) : 0; }
  P(c, r) { return this.T.point(c, r); }
  mat(key) {
    if (this.mc[key]) return this.mc[key];
    const [c, m, r] = ZMAT[key];
    const flat = ['rock', 'rockDark', 'stone', 'stone2', 'obsidian', 'darkStone'].includes(key);
    return (this.mc[key] = new THREE.MeshStandardMaterial({ color: c, metalness: m, roughness: r, flatShading: flat }));
  }
  toonM(col) { const k = 'toon' + col; return this.mc[k] || (this.mc[k] = toon(col)); }
  glow(color, k = 2.5) { const key = 'g' + color + k; return this.mc[key] || (this.mc[key] = glowMat(color, k)); }
  M(m) { return typeof m === 'string' ? (ZMAT[m] ? this.mat(m) : this.toonM(m)) : m; }
  add(o) { o.traverse(x => { if (x.isMesh) { x.castShadow = true; x.receiveShadow = true; } }); this.scene.add(o); return o; }
  mesh(geo, mat, x, y, z, o = {}) {
    const m = new THREE.Mesh(geo, this.M(mat));
    m.position.set(x, y + (o.parent || o.abs ? 0 : this.gy(x, z)), z); if (o.ry) m.rotation.y = o.ry; if (o.rx) m.rotation.x = o.rx; if (o.rz) m.rotation.z = o.rz;
    if (o.parent) o.parent.add(m); else this.add(m);
    if (o.noShadow) m.castShadow = false;
    return m;
  }
  colBox(x, z, hw, hd, top) { this.v.colliders.push({ box: true, x, z, hw, hd, top, y: this.T ? this.gy(x, z) : undefined }); }
  col(x, z, r, top) { this.v.colliders.push({ x, z, r, top, y: this.T ? this.gy(x, z) : undefined }); }
  box(x, z, w, h, d, mat, o = {}) {
    const geo = o.round ? new THREEX.RoundedBoxGeometry(w, h, d, 2, Math.min(w, h, d) * 0.1) : new THREE.BoxGeometry(w, h, d);
    const m = this.mesh(geo, mat, x, (o.y || 0) + h / 2, z, o);
    if (o.col !== false && (o.y || 0) < 1.6) {
      const ry = ((o.ry || 0) % Math.PI + Math.PI) % Math.PI, top = (o.y || 0) + h;
      if (ry < 0.05 || ry > Math.PI - 0.05) this.colBox(x, z, w / 2, d / 2, top);
      else if (Math.abs(ry - Math.PI / 2) < 0.05) this.colBox(x, z, d / 2, w / 2, top);
      else this.col(x, z, Math.max(w, d) * 0.45, top);
    }
    return m;
  }
  cyl(x, z, r, h, mat, o = {}) {
    const m = this.mesh(new THREE.CylinderGeometry(o.r2 ?? r, r, h, o.seg || 16, 1, !!o.open), mat, x, (o.y || 0) + h / 2, z, o);
    if (o.col !== false && (o.y || 0) < 1.6) this.col(x, z, Math.max(r, o.r2 || 0), (o.y || 0) + h);
    return m;
  }
  light(x, y, z, color, intensity = 8, dist = 16) {
    if (this.lights >= 4) return null;
    this.lights++;
    const l = new THREE.PointLight(color, intensity, dist, 1.6); l.position.set(x, y + this.gy(x, z), z); this.scene.add(l); return l;
  }
  tick(fn) { this.v.zoneTicks.push(fn); }
  spot(pad = 2) { return this.v.freeSpot(pad); }
  scatter(n, pad, fn) { for (let i = 0; i < n; i++) { const p = this.spot(pad); fn(p.x, p.z, i); } }
  near(x, z, r) { return this.v.reserved.some(p => Math.hypot(p.x - x, p.z - z) < p.r + r); }
  reserve(x, z, r) { this.v.reserved.push({ x, z, r }); }
  batch(mat) {
    const key = typeof mat === 'string' ? mat : mat.uuid;
    this.batches = this.batches || {};
    return (this.batches[key] = this.batches[key] || { acc: new GeoAcc(4), mat: this.M(mat) }).acc;
  }
  flush() {
    for (const b of Object.values(this.batches || {})) { const m = b.acc.mesh(b.mat); if (m) { m.castShadow = true; this.scene.add(m); } }
    this.batches = {};
    // 形の違う部品（町の建物など）は、材質ごとに一つのジオメトリにまとめて描く
    for (const b of Object.values(this.merged || {})) {
      if (!b.list.length) continue;
      const m = new THREE.Mesh(THREEX.BufferGeometryUtils.mergeGeometries(b.list), b.mat);
      m.castShadow = !b.noShadow; m.receiveShadow = true;
      this.scene.add(m);
    }
    this.merged = {};
    // 同じ形の部品（木の幹・葉・岩など）は InstancedMesh でまとめて描く
    const M4 = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler(), sc = V3(), pos = V3(), col = new THREE.Color();
    for (const it of Object.values(this.insts || {})) {
      if (!it.list.length) continue;
      const m = new THREE.InstancedMesh(it.geo, it.mat, it.list.length);
      it.list.forEach(([x, y, z, s, rot, c], i) => {
        e.set(rot ? rot[0] : 0, rot ? rot[1] : 0, rot ? rot[2] : 0); q.setFromEuler(e);
        if (Array.isArray(s)) sc.set(s[0], s[1], s[2]); else sc.set(s, s, s);
        M4.compose(pos.set(x, y, z), q, sc); m.setMatrixAt(i, M4);
        m.setColorAt(i, col.set(c || '#ffffff'));
      });
      m.castShadow = !it.noShadow; m.receiveShadow = true; m.computeBoundingSphere();
      this.scene.add(m);
    }
    this.insts = {};
  }
  // ---------------- 木立（地形マップの # に木を植える） ----------------
  // 部品の型：形は単位の大きさ（幹と円錐は根もとが原点）。色は1本ごとに変える
  part(key) {
    this.insts = this.insts || {};
    if (this.insts[key]) return this.insts[key];
    const up = g => { g.translate(0, 0.5, 0); return g; };
    const std = (o = {}) => new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 0.88, metalness: 0, ...o });
    const glow = () => new THREE.MeshBasicMaterial({ color: '#ffffff', toneMapped: false });
    const def = {
      trunk: [up(new THREE.CylinderGeometry(0.7, 1, 1, 7)), std({ roughness: 0.95 })],
      blob: [new THREE.IcosahedronGeometry(1, 1), std({ roughness: 0.85 })],
      cone: [up(new THREE.ConeGeometry(1, 1, 8)), std({ roughness: 0.85 })],
      rock: [new THREE.DodecahedronGeometry(1, 0), std({ roughness: 0.95, flatShading: true })],
      cap: [new THREE.SphereGeometry(1, 14, 8, 0, Math.PI * 2, 0, Math.PI / 2), std({ roughness: 0.6 })],
      stick: [up(new THREE.CylinderGeometry(1, 1, 1, 6)), std({ roughness: 0.8 })],
      ring: [new THREE.TorusGeometry(1, 0.4, 8, 18), std({ roughness: 0.4 })],
      ball: [new THREE.SphereGeometry(1, 12, 10), std({ roughness: 0.45 })],
      gem: [new THREE.OctahedronGeometry(1, 0), glow(), true],
      dot: [new THREE.SphereGeometry(1, 8, 6), glow(), true],
    }[key];
    return (this.insts[key] = { geo: def[0], mat: def[1], list: [], noShadow: !!def[2] });
  }
  put(key, x, y, z, s, rot, color) { this.part(key).list.push([x, y, z, s, rot, color]); }
  // 色を少しだけばらつかせる
  tint(c, k = 0.08) { const col = new THREE.Color(c), v = 1 + (this.r() - 0.5) * k * 2; return col.multiplyScalar(v).getStyle(); }
  // 1本の木（kind：round 丸い木／pine 針葉樹／dead 枯れ木／spooky 魔王領の木／mush 大きなきのこ／candy お菓子／crystal 水晶）
  plant(kind, x, y, z, s = 1, o = {}) {
    const r = this.r, leaf = () => this.tint(pick(o.leaf || ['#5ab04a', '#4a9a3e', '#6abf52']), 0.1), bark = this.tint(o.bark || '#7a5a3a');
    switch (kind) {
      case 'pine':
        this.put('trunk', x, y, z, [0.2 * s, 1.3 * s, 0.2 * s], null, bark);
        for (let i = 0; i < 3; i++) this.put('cone', x, y + (1.0 + i * 0.9) * s, z, [(1.4 - i * 0.36) * s, 1.8 * s, (1.4 - i * 0.36) * s], [0, r() * 3, 0], this.tint(pick(o.pine || ['#3a7a44', '#2e6a3a', '#447e48']), 0.08));
        break;
      case 'dead':
        this.put('trunk', x, y, z, [0.2 * s, 2.8 * s, 0.2 * s], null, this.tint(o.deadBark || '#6a5a4a'));
        for (let i = 0; i < 4; i++) { const a = i * 1.6 + r(); this.put('stick', x, y + (1.5 + i * 0.3) * s, z, [0.05 * s, 1.2 * s, 0.05 * s], [Math.sin(a) * 0.9, 0, Math.cos(a) * 0.9], this.tint(o.deadBark || '#6a5a4a')); }
        break;
      case 'spooky':
        this.put('trunk', x, y, z, [0.22 * s, 2.6 * s, 0.22 * s], null, this.tint('#3a3048'));
        for (let i = 0; i < 3; i++) { const a = i * 2.1 + r(); this.put('stick', x, y + (1.6 + i * 0.3) * s, z, [0.05 * s, 1.1 * s, 0.05 * s], [Math.sin(a) * 1.0, 0, Math.cos(a) * 1.0], '#3a3048'); }
        this.put('blob', x, y + 3.0 * s, z, [1.2 * s, 0.95 * s, 1.2 * s], [0, r() * 3, 0], this.tint(pick(o.leaf || ['#7a4a9a', '#6a3a8a', '#8a5aa8'])));
        for (let i = 0; i < 3; i++) { const a = r() * 6; this.put('dot', x + Math.cos(a) * 1.0 * s, y + (2.6 + r() * 0.6) * s, z + Math.sin(a) * 1.0 * s, 0.1 * s, null, '#ff8ad8'); }
        break;
      case 'mush': {
        const cap = pick(o.caps || ['#e05a6a', '#ffb84a', '#b88aff']);
        this.put('stick', x, y, z, [0.28 * s, 1.5 * s, 0.28 * s], null, this.tint('#fff0dc', 0.04));
        this.put('cap', x, y + 1.35 * s, z, [1.3 * s, 0.85 * s, 1.3 * s], null, this.tint(cap));
        for (let i = 0; i < 4; i++) { const a = i * 1.6 + r(); this.put('ball', x + Math.cos(a) * 0.7 * s, y + 1.35 * s + 0.62 * s, z + Math.sin(a) * 0.7 * s, 0.13 * s, null, '#fff8f0'); }
        break;
      }
      case 'candy': {
        const c = pick(['#ffb8d8', '#b8e0ff', '#fff0a8', '#c8ffc8']);
        this.put('stick', x, y, z, [0.12 * s, 2.4 * s, 0.12 * s], null, '#fff8ec');
        if (r() < 0.5) this.put('ring', x, y + 2.9 * s, z, 0.75 * s, [0, r() * 3, 0], c);
        else this.put('ball', x, y + 2.8 * s, z, 0.95 * s, null, c);
        break;
      }
      case 'crystal':
        for (let i = 0; i < 4; i++) { const h = (0.6 + r() * 1.0) * s; this.put('gem', x + (r() - 0.5) * s, y + h * 0.4, z + (r() - 0.5) * s, [0.3 * s, h * 1.1, 0.3 * s], [(r() - 0.5) * 0.7, r() * 3, (r() - 0.5) * 0.7], o.gem || '#a07bff'); }
        this.put('rock', x, y + 0.2 * s, z, [0.8 * s, 0.5 * s, 0.8 * s], [0, r() * 3, 0], this.tint(o.rock || '#4a4450'));
        break;
      default: {   // round
        this.put('trunk', x, y, z, [0.2 * s, 1.9 * s, 0.2 * s], null, bark);
        for (let i = 0; i < 3; i++) { const a = i / 3 * Math.PI * 2 + r(); this.put('blob', x + Math.cos(a) * 0.55 * s, y + (2.2 + r() * 0.45) * s, z + Math.sin(a) * 0.55 * s, [(0.95 + r() * 0.3) * s, 0.82 * s, (0.95 + r() * 0.3) * s], [0, r() * 3, 0], leaf()); }
        this.put('blob', x, y + 2.85 * s, z, [1.05 * s, 0.92 * s, 1.05 * s], [0, r() * 3, 0], leaf());
        if (o.fruit && r() < 0.3) for (let i = 0; i < 4; i++) { const a = r() * 6; this.put('dot', x + Math.cos(a) * 1.0 * s, y + (2.3 + r() * 0.6) * s, z + Math.sin(a) * 1.0 * s, 0.12 * s, null, o.fruit); }
      }
    }
  }
  shrub(x, y, z, s = 1, o = {}) {
    for (let i = 0; i < 3; i++) this.put('blob', x + (i - 1) * 0.45 * s, y + 0.35 * s, z + (this.r() - 0.5) * 0.4 * s, [0.55 * s, 0.42 * s, 0.55 * s], [0, this.r() * 3, 0], this.tint(pick(o.bushLeaf || o.leaf || ['#4a9a3e', '#5aa848'])));
    if (o.flower && this.r() < 0.5) for (let i = 0; i < 3; i++) this.put('dot', x + (this.r() - 0.5) * 1.1 * s, y + 0.62 * s, z + (this.r() - 0.5) * 0.6 * s, 0.08 * s, null, pick(o.flower));
  }
  // 地形マップの木立（#）すべてに木を植え、道に面した縁は茂みと岩ですき間をふさぐ
  // o.trees：[[種類, 重み], ...]、o.leaf／o.bark：色、o.bush：縁の茂みの割合、o.rocks：縁の岩の割合、o.skip(x, z)：植えない場所
  flora(o = {}) {
    const T = this.T; if (!T || T.outdoor !== 'flora') return;
    const r = this.r, kinds = o.trees || [['round', 1]], total = kinds.reduce((a, k) => a + k[1], 0);
    const kindOf = () => { let v = r() * total; for (const k of kinds) if ((v -= k[1]) <= 0) return k[0]; return kinds[0][0]; };
    for (let i = 0; i < T.kind.length; i++) {
      if (T.kind[i] > TK.WINDOW || T.water[i]) continue;
      const c = T.colOf(i), rw = T.rowOf(i), x = T.cx(c), z = T.cz(rw), y = T.cap[i], d = T.dist[i] < 0 ? 9 : T.dist[i];
      if (o.skip && o.skip(x, z)) continue;
      if (d >= 4 && r() < 0.4) continue;   // 奥の木はまばらに大きく
      const s = (o.size || 1) * (0.85 + r() * 0.45) * (d >= 3 ? 1.25 : 1);
      this.plant(kindOf(), x + (r() - 0.5) * 0.9, y, z + (r() - 0.5) * 0.9, s, o);
      if (d !== 1) continue;
      DIR4.forEach(([dc, dr]) => {
        const j = T.idx(c + dc, rw + dr); if (j < 0 || !T.isWalkKind(T.kind[j]) || Math.abs(T.h[j] - y) > 0.3) return;
        const bx = x + dc * 0.55 + dr * (r() - 0.5) * 1.2, bz = z + dr * 0.55 + dc * (r() - 0.5) * 1.2;
        if (r() < (o.bush ?? 0.75)) this.shrub(bx, y, bz, 0.8 + r() * 0.5, o);
        else if (r() < (o.rocks ?? 0.35)) this.put('rock', bx, y + 0.2, bz, [0.5 + r() * 0.3, 0.35 + r() * 0.2, 0.5 + r() * 0.3], [0, r() * 3, 0], this.tint(o.rock || '#9a9488'));
      });
    }
  }
  // 岩の崖（crag）の上にも、ところどころ木や岩を置く
  cragTop(o = {}) {
    const T = this.T; if (!T || T.outdoor !== 'cliff') return;
    const r = this.r, kinds = o.trees || [['round', 1]], total = kinds.reduce((a, k) => a + k[1], 0);
    const kindOf = () => { let v = r() * total; for (const k of kinds) if ((v -= k[1]) <= 0) return k[0]; return kinds[0][0]; };
    for (let i = 0; i < T.kind.length; i++) {
      if (T.kind[i] !== TK.SOLID || T.water[i] || r() > (o.density ?? 0.3)) continue;
      const x = T.cx(T.colOf(i)) + (r() - 0.5), z = T.cz(T.rowOf(i)) + (r() - 0.5);
      if (o.skip && o.skip(x, z)) continue;
      if (r() < (o.rockShare ?? 0.3)) this.put('rock', x, T.cap[i] + 0.2, z, [0.6 + r() * 0.6, 0.4 + r() * 0.4, 0.6 + r() * 0.6], [0, r() * 3, 0], this.tint(o.rock || '#8a8478'));
      else this.plant(kindOf(), x, T.cap[i], z, (o.size || 0.9) * (0.8 + r() * 0.4), o);
    }
  }

  // ---------------- 外周 ----------------
  perimeter(style) {
    const Z = this.zone, hw = Z.w / 2, hd = Z.d / 2;
    const gaps = Z.exits.map(e => ({ ...e, ...exitPos(Z, e) }));
    const edges = [
      { side: 'n', len: Z.w, pos: t => [t, -hd], ry: 0 }, { side: 's', len: Z.w, pos: t => [t, hd], ry: 0 },
      { side: 'w', len: Z.d, pos: t => [-hw, t], ry: Math.PI / 2 }, { side: 'e', len: Z.d, pos: t => [hw, t], ry: Math.PI / 2 },
    ];
    for (const ed of edges) {
      const seg = { fence: 2.4, forest: 3.2, rock: 3.4, wall: 4, roots: 4, cloud: 5, void: 3, candy: 3 }[style] || 3;
      for (let t = -ed.len / 2 + seg / 2; t < ed.len / 2; t += seg) {
        if (gaps.some(g => g.side === ed.side && Math.abs(g.at - t) < 3.4)) continue;
        const [x, z] = ed.pos(t);
        this.wallPiece(style, x, z, ed.ry, seg, t, ed.side);
      }
    }
  }
  wallPiece(style, x, z, ry, seg, t, side) {
    const r = this.r;
    const out = { n: [0, -1], s: [0, 1], w: [-1, 0], e: [1, 0] }[side];
    switch (style) {
      case 'fence': {
        this.batch('wood').box(x - (ry ? 0.08 : seg / 2), 0.55, z - (ry ? seg / 2 : 0.08), x + (ry ? 0.08 : seg / 2), 0.68, z + (ry ? seg / 2 : 0.08));
        this.batch('wood').box(x - (ry ? 0.08 : seg / 2), 0.22, z - (ry ? seg / 2 : 0.08), x + (ry ? 0.08 : seg / 2), 0.32, z + (ry ? seg / 2 : 0.08));
        this.batch('wood2').box(x - 0.1, 0, z - 0.1, x + 0.1, 0.9, z + 0.1);
        if (r() < 0.5) this.bush(x + out[0] * 1.6, z + out[1] * 1.6, 0.8 + r() * 0.6);
        break;
      }
      case 'forest': {
        const s = 1 + r() * 0.9; this.roundTree(x + out[0] * (1 + r() * 2), z + out[1] * (1 + r() * 2), s, r() < 0.5 ? 'leaf' : 'leaf2');
        if (r() < 0.6) this.bush(x - out[0] * 0.5 + (r() - 0.5) * 2, z - out[1] * 0.5 + (r() - 0.5) * 2, 0.9 + r() * 0.5);
        break;
      }
      case 'rock': { const s = 1.6 + r() * 2; const m = this.mesh(new THREE.DodecahedronGeometry(s, 0), 'rock', x + out[0] * 1.2, s * 0.5, z + out[1] * 1.2, { ry: r() * 3 }); m.scale.y = 0.8 + r() * 0.8; break; }
      case 'wall': {
        this.box(x, z, ry ? 0.9 : seg, 4.2, ry ? seg : 0.9, 'stone', { col: false });
        this.box(x, z, ry ? 1.1 : seg, 0.35, ry ? seg : 1.1, 'stone2', { y: 4.2, col: false });
        if (Math.round(t / seg) % 2 === 0) this.box(x, z, ry ? 1.1 : 1.1, 0.8, ry ? 1.1 : 1.1, 'stone2', { y: 4.5, col: false });
        break;
      }
      case 'roots': {
        const len = 5 + r() * 4, m = this.mesh(new THREE.CylinderGeometry(0.5, 1.4, len, 8), 'bark', x + out[0], len * 0.28, z + out[1], { rz: (r() - 0.5) * 1.2, rx: (r() - 0.5) * 1.2 });
        break;
      }
      case 'void': {
        if (r() < 0.5) { const s = 1 + r() * 1.5; this.mesh(new THREE.DodecahedronGeometry(s, 0), 'darkStone', x + out[0] * 1.5, -0.3, z + out[1] * 1.5, { ry: r() * 3 }); }
        this.mesh(new THREE.BoxGeometry(ry ? 0.1 : seg, 0.06, ry ? seg : 0.1), this.glow('#b8a8ff', 1.8), x, 0.04, z, { noShadow: true });
        break;
      }
      case 'candy': { const c = ['candyPink', 'candyBlue', 'candyYellow'][Math.floor(r() * 3)]; this.cyl(x + out[0], z + out[1], 0.25, 2.4 + r() * 2, 'cream', { col: false, seg: 8 }); this.mesh(new THREE.SphereGeometry(0.9 + r() * 0.5, 14, 10), c, x + out[0], 3.2 + r() * 1.5, z + out[1]); break; }
    }
  }

  // ---------------- まとめて描く部品（町の建物） ----------------
  // 色から標準の材質（色ごとに共有）
  stdM(color, rough = 0.85, o = {}) { const k = 'std' + color + rough + (o.emissive || '') + (o.side || ''); return this.mc[k] || (this.mc[k] = new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: 0.02, ...o })); }
  // ジオメトリを置いて（位置・回転・拡大）、材質ごとの束に加える。mat は ZMAT の名前・色・材質
  mg(mat, geo, x, y, z, rot = null, sc = null) {
    const M = typeof mat === 'string' && !ZMAT[mat] ? this.stdM(mat) : this.M(mat), k = M.uuid, b = (this.merged = this.merged || {})[k] || (this.merged[k] = { mat: M, list: [], noShadow: !!M.userData.noShadow });
    const e = rot ? new THREE.Euler(rot[0] || 0, rot[1] || 0, rot[2] || 0) : new THREE.Euler();
    geo.applyMatrix4(new THREE.Matrix4().compose(V3(x, y, z), new THREE.Quaternion().setFromEuler(e), sc ? V3(...sc) : V3(1, 1, 1)));
    let g = geo.index ? geo.toNonIndexed() : geo;
    for (const a of Object.keys(g.attributes)) if (!['position', 'normal', 'uv'].includes(a)) g.deleteAttribute(a);
    if (!g.attributes.uv) g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(g.attributes.position.count * 2), 2));
    g.clearGroups(); b.list.push(g);
    return g;
  }
  // 壁の面に沿って置く：面の中心 (fx, fz)、外向きの法線 (nx, nz)。u = 面に沿った位置、y = 高さ、out = 壁からの張り出し
  mgFace(mat, geo, f, u, y, out, rz = 0) {
    this.mg(mat, geo, f.x + f.ax * u + f.nx * out, y, f.z + f.az * u + f.nz * out, [0, f.ry, rz]);
  }
  // 地図の敷地（#）を長方形に分け、一棟ずつ家を建てる。o.happy：色が戻った街、o.skip(c, r)：建てないマス
  townBlocks(o = {}) {
    const T = this.T; if (!T) return [];
    const used = new Uint8Array(T.kind.length), r = this.r, rects = [];
    const lot = (c, rr, b) => { const i = T.idx(c, rr); return i >= 0 && T.kind[i] === TK.SOLID && !T.water[i] && !used[i] && !(o.skip && o.skip(c, rr)) && (b == null || Math.abs(T.base[i] - b) < 0.01); };
    for (let rr = 0; rr < T.rows; rr++) for (let c = 0; c < T.cols; c++) {
      if (!lot(c, rr)) continue;
      const b = T.base[T.idx(c, rr)], maxW = 2 + Math.floor(r() * 3), maxD = 2 + Math.floor(r() * 3);
      let w = 1; while (w < maxW && lot(c + w, rr, b)) w++;
      let d = 1; while (d < maxD && [...Array(w)].every((_, k) => lot(c + k, rr + d, b))) d++;
      for (let y = 0; y < d; y++) for (let x = 0; x < w; x++) used[T.idx(c + x, rr + y)] = 1;
      rects.push({ c, r: rr, w, d, base: b });
    }
    rects.forEach(R => this.townHouse(R, o));
    return rects;
  }
  // 一棟の家：石の土台、漆喰の壁と木組み、窓（鎧戸・花の箱）、表の扉と日よけ、猫耳のついた切妻屋根と煙突。1マスの敷地は塔
  townHouse(R, o = {}) {
    const T = this.T, r = this.r, happy = !!o.happy;
    const x0 = T.cx(R.c) - CELL / 2, x1 = T.cx(R.c + R.w - 1) + CELL / 2, z0 = T.cz(R.r) - CELL / 2, z1 = T.cz(R.r + R.d - 1) + CELL / 2;
    const W = x1 - x0, D = z1 - z0, cx = (x0 + x1) / 2, cz = (z0 + z1) / 2, y0 = R.base;
    // 四方のとなり：歩ける床のマス数といちばん高い床（見える面にだけ窓や扉をつける）
    const sides = {};
    for (const [k, dc, dr] of [['s', 0, 1], ['e', 1, 0], ['w', -1, 0], ['n', 0, -1]]) {
      let n = 0, hi = -1e9;
      const len = dc ? R.d : R.w;
      for (let q = 0; q < len; q++) {
        const c = dc ? (dc > 0 ? R.c + R.w : R.c - 1) : R.c + q, rr = dr ? (dr > 0 ? R.r + R.d : R.r - 1) : R.r + q, j = T.idx(c, rr);
        if (j >= 0 && T.isWalkKind(T.kind[j])) { n++; hi = Math.max(hi, T.base[j]); }
      }
      sides[k] = { k, n, hi, nx: dc, nz: dr, len: dc ? D : W, x: cx + dc * W / 2, z: cz + dr * D / 2, ax: dr ? 1 : 0, az: dc ? 1 : 0, ry: Math.atan2(dc, dr) };
    }
    const vis = Object.values(sides).filter(s => s.n > 0), front = vis.sort((a, b) => b.n - a.n)[0] || null;
    const tower = R.w === 1 && R.d === 1;
    const hiNb = Math.max(y0, ...Object.values(sides).map(s => s.hi));
    const SH = 2.6, PL = 0.6;
    let st = tower ? 3 : 2 + (r() < 0.45 ? 1 : 0) + (vis.length === 0 ? 1 : 0);
    while (y0 + PL + st * SH < hiNb + 3.2) st++;
    const top = y0 + PL + st * SH;
    const pick2 = a => a[Math.floor(r() * a.length)];
    const wallC = happy ? pick2(['#fff4e2', '#ffe8d4', '#fde2e8', '#e8f0ff', '#fff2c8', '#e8f4e0', '#f4e8ff']) : pick2(['#d8d4d0', '#cfcac6', '#c6c2be', '#e0dcd8']);
    const roofC = happy ? pick2(['#e05a4a', '#5a8ad8', '#5aa860', '#f09a4a', '#8a6ad8', '#e87aa8', '#3aa8a8']) : pick2(['#8a8a96', '#7a7a86', '#9a9aa4', '#6e6e7a']);
    const wood = happy ? '#7a4a30' : '#5e5652', stone = happy ? 'stone' : 'stone2';
    const glass = this.glassM || (this.glassM = new THREE.MeshStandardMaterial({ color: '#7aa8d0', roughness: 0.15, metalness: 0.35, emissive: '#2a4a6a', emissiveIntensity: 0.35 }));
    const lit = this.litM || (this.litM = glowMat('#ffd8a0', 1.3));
    const B = (w, h, d) => new THREE.BoxGeometry(w, h, d);
    // 壁と土台、軒の帯と各階の梁
    this.mg(wallC, B(W - 0.04, top - y0, D - 0.04), cx, (y0 + top) / 2, cz);
    this.mg(stone, B(W + 0.12, PL + 0.1, D + 0.12), cx, y0 + (PL + 0.1) / 2, cz);
    this.mg(wood, B(W + 0.28, 0.24, D + 0.28), cx, top - 0.1, cz);
    for (let k = 1; k < st; k++) this.mg(wood, B(W + 0.1, 0.16, D + 0.1), cx, y0 + PL + k * SH, cz);
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) this.mg(wood, B(0.26, top - y0 - PL, 0.26), cx + sx * (W / 2 - 0.08), y0 + PL + (top - y0 - PL) / 2, cz + sz * (D / 2 - 0.08));
    const timbered = r() < 0.5, shutters = r() < 0.6, flowers = r() < 0.55, shop = front && r() < 0.5;
    const shutterC = roofC;
    // 窓・扉：見える面ごと
    for (const f of vis) {
      const n = Math.max(1, Math.floor((f.len - 0.6) / 2.2)), step = f.len / n;
      const doorAt = f === front ? Math.floor(n / 2) : -1;
      const floorY = Math.max(y0, Math.min(f.hi, top - SH));   // この面に接する床の高さ（高台に面した家は、高台の高さに扉）
      const doorSt = Math.max(0, Math.min(st - 1, Math.floor((floorY - y0) / SH + 0.01)));
      for (let s = 0; s < st; s++) {
        const yb = y0 + PL + s * SH;
        if (yb + 1.4 < floorY) continue;   // 高台より下の階（擁壁に隠れる）には窓をつけない
        for (let q = 0; q < n; q++) {
          const u = -f.len / 2 + step * (q + 0.5);
          if (Math.abs(u) > f.len / 2 - 0.55) continue;
          if (q === doorAt && s === doorSt) {
            // 扉：石の枠、木の扉、踏み石。店なら日よけ
            const dy = floorY;
            this.mgFace(stone, B(1.5, 2.45, 0.14), f, u, dy + 1.22, 0.03);
            this.mgFace(happy ? '#6a4028' : '#4a4240', B(1.12, 2.1, 0.12), f, u, dy + 1.05, 0.08);
            this.mgFace('gold', new THREE.SphereGeometry(0.06, 8, 6), f, u + 0.35, dy + 1.0, 0.18);
            this.mgFace(stone, B(1.7, 0.16, 0.5), f, u, dy + 0.08, 0.26);
            if (shop) {
              const c1 = happy ? pick2(['#e05a4a', '#5a8ad8', '#5aa860', '#f09a4a', '#e87aa8']) : '#9a9aa4', c2 = happy ? '#fff8f0' : '#c8c8cc';
              for (let t = 0; t < 4; t++) this.mgFace(t % 2 ? c2 : c1, B(0.52, 0.06, 1.1), f, u - 0.78 + t * 0.52, dy + 2.62, 0.5, 0);
            }
            this.mgFace(lit, B(0.22, 0.3, 0.22), f, u + 1.0, dy + 2.1, 0.22);
            this.mgFace('iron', B(0.05, 0.05, 0.3), f, u + 1.0, dy + 2.3, 0.12);
            continue;
          }
          const wy = yb + 1.45;
          this.mgFace(wood, B(1.02, 1.32, 0.1), f, u, wy, 0.03);
          this.mgFace(happy && (s === 0 || r() < 0.25) ? lit : glass, B(0.8, 1.1, 0.06), f, u, wy, 0.07);
          this.mgFace(wood, B(0.06, 1.1, 0.08), f, u, wy, 0.1);
          this.mgFace(wood, B(0.8, 0.06, 0.08), f, u, wy + 0.1, 0.1);
          this.mgFace(stone, B(1.12, 0.1, 0.26), f, u, wy - 0.68, 0.12);
          if (shutters) for (const sd of [-1, 1]) this.mgFace(shutterC, B(0.36, 1.22, 0.05), f, u + sd * 0.72, wy, 0.05);
          if (flowers && s > 0) {
            this.mgFace(wood, B(0.9, 0.22, 0.26), f, u, wy - 0.82, 0.2);
            for (let t = 0; t < 4; t++) this.mgFace(happy ? pick2(['#ff8ab8', '#ffd24a', '#ffffff', '#ff6a5a', '#b88aff']) : '#8a8478', new THREE.SphereGeometry(0.12, 6, 5), f, u - 0.3 + t * 0.2, wy - 0.62, 0.22);
          }
        }
        // 木組み（斜めの筋交い）
        if (timbered && s > 0) for (let q = 0; q <= n; q++) {
          const u = -f.len / 2 + step * q;
          if (Math.abs(u) > f.len / 2 - 0.2) continue;
          this.mgFace(wood, B(0.14, SH * 0.95, 0.06), f, u, yb + SH / 2, 0.04);
        }
      }
      // バルコニー（表の二階）
      if (f === front && st >= 2 && f.len >= 4 && r() < 0.4) {
        const by = Math.max(y0, floorY) + PL + SH, bw = Math.min(f.len - 1.2, 3.6);
        this.mgFace(stone, B(bw, 0.16, 0.9), f, 0, by, 0.45);
        this.mgFace('iron', B(bw, 0.06, 0.06), f, 0, by + 1.0, 0.86);
        for (let t = 0; t <= 8; t++) this.mgFace('iron', B(0.04, 0.9, 0.04), f, -bw / 2 + bw * t / 8, by + 0.53, 0.86);
      }
    }
    // 屋根
    if (tower) {
      const cone = new THREE.ConeGeometry(1.75, 3.2, 4); cone.rotateY(Math.PI / 4);
      this.mg(roofC, cone, cx, top + 1.6, cz);
      this.mg('iron', new THREE.CylinderGeometry(0.03, 0.03, 1.4, 5), cx, top + 3.8, cz);
      this.mg(happy ? pick2(['#ff6a8a', '#ffd27a', '#6ad8ff']) : '#b0b0b8', B(0.02, 0.4, 0.6), cx, top + 4.2, cz + 0.3);
      return;
    }
    const alongX = W >= D, L = alongX ? W : D, S = alongX ? D : W, RH = Math.min(3.2, S * 0.42), ov = 0.35;
    const ridgeRy = alongX ? Math.PI / 2 : 0;
    const place = (mat, geo, lx, ly, lz, rz = 0, sc) => {
      const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(0, ridgeRy, 0));
      const p = V3(lx, ly, lz).applyQuaternion(q);
      this.mg(mat, geo, cx + p.x, top + p.y, cz + p.z, [0, ridgeRy, rz], sc);
    };
    const tri = new THREE.Shape(); tri.moveTo(-S / 2, 0); tri.lineTo(0, RH); tri.lineTo(S / 2, 0); tri.closePath();
    const prism = new THREE.ExtrudeGeometry(tri, { depth: L - 0.04, bevelEnabled: false }); prism.translate(0, 0, -(L - 0.04) / 2);
    place(wallC, prism, 0, 0, 0);
    const a = Math.atan2(RH, S / 2), sl = Math.hypot(S / 2, RH) + ov;
    for (const sd of [-1, 1]) {
      const mx = sd * (S / 4 + Math.cos(a) * ov / 2 * 1) , my = RH / 2 - Math.sin(a) * ov / 2 + 0.1;
      place(roofC, B(sl, 0.18, L + ov * 2), mx + sd * 0.02, my, 0, -sd * a);
    }
    place(roofC, B(0.34, 0.24, L + ov * 2 + 0.02), 0, RH + 0.1, 0);
    for (const sd of [-1, 1]) { const ear = new THREE.ConeGeometry(0.42, 0.8, 4); ear.rotateY(Math.PI / 4); place(roofC, ear, 0, RH + 0.5, sd * (L / 2 + ov - 0.2), 0, [1, 1, 0.5]); }
    if (r() < 0.55) place(stone, B(0.6, 1.8, 0.6), S * 0.22, RH * 0.55 + 0.4, (r() - 0.5) * L * 0.5);
  }
  // ---------------- 町の小物 ----------------
  // 街灯：鉄の柱と腕、灯り（光のにじみつき）
  streetLamp(x, z, happy = true, h = 3.8) {
    const y = this.gy(x, z), col = happy ? '#ffd8a0' : '#dcdce4';
    this.mg('iron', new THREE.CylinderGeometry(0.07, 0.11, h, 8), x, y + h / 2, z);
    this.mg('iron', new THREE.CylinderGeometry(0.2, 0.26, 0.4, 8), x, y + 0.2, z);
    this.mg('iron', new THREE.BoxGeometry(0.9, 0.06, 0.06), x + 0.4, y + h - 0.1, z);
    this.mg(this.glow(col, happy ? 2.2 : 1.1), new THREE.BoxGeometry(0.3, 0.42, 0.3), x + 0.8, y + h - 0.45, z);
    this.mg('iron', new THREE.ConeGeometry(0.28, 0.24, 4), x + 0.8, y + h - 0.12, z, [0, Math.PI / 4, 0]);
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex(), color: hdr(col, happy ? 0.55 : 0.25), blending: THREE.AdditiveBlending, depthWrite: false }));
    sp.scale.setScalar(1.8); sp.position.set(x + 0.8, y + h - 0.45, z); this.scene.add(sp);
    this.col(x, z, 0.2, h);
  }
  // 旗飾り：両端の柱のあいだに、三角の旗をたるませて張る
  bunting(x0, z0, x1, z1, cols, h = 5, poles = true) {
    const ya = this.gy(x0, z0) + h, yb = this.gy(x1, z1) + h, len = Math.hypot(x1 - x0, z1 - z0), n = Math.max(4, Math.round(len / 0.9)), ry = Math.atan2(x1 - x0, z1 - z0);
    for (let i = 0; i <= n; i++) {
      const t = i / n, y = lerp(ya, yb, t) - Math.sin(t * Math.PI) * Math.min(1.2, len * 0.05);
      const g = new THREE.ConeGeometry(0.28, 0.55, 3); g.rotateZ(Math.PI);
      this.mg(this.stdM(cols[i % cols.length], 0.9, { side: THREE.DoubleSide }), g, lerp(x0, x1, t), y - 0.3, lerp(z0, z1, t), [0, ry + Math.PI / 2, 0], [1, 1, 0.15]);
    }
    if (poles) for (const [x, z, y] of [[x0, z0, ya], [x1, z1, yb]]) { this.mg('wood2', new THREE.CylinderGeometry(0.08, 0.1, h + 0.3, 6), x, y - h / 2 + 0.15, z); this.col(x, z, 0.15, h); }
  }
  // 垂れ幕（ry = 正面）：上端 y0 から長さ h
  banner(x, z, ry, y0, h, col, trim = '#ffd27a', w = 1.2) {
    this.mg(this.stdM(col, 0.9, { side: THREE.DoubleSide }), new THREE.PlaneGeometry(w, h), x, y0 - h / 2, z, [0, ry, 0]);
    this.mg(trim, new THREE.BoxGeometry(w + 0.2, 0.08, 0.08), x, y0, z, [0, ry, 0]);
    const tip = new THREE.ConeGeometry(w / 2, 0.5, 3); tip.rotateZ(Math.PI);
    this.mg(this.stdM(col, 0.9, { side: THREE.DoubleSide }), tip, x, y0 - h - 0.2, z, [0, ry, 0], [1, 1, 0.05]);
  }
  // 丸い植え込みと木
  planterTree(x, z, s = 1, happy = true) {
    this.cyl(x, z, 0.9 * s, 0.55, 'stone', { seg: 14 });
    this.mesh(new THREE.CylinderGeometry(0.8 * s, 0.8 * s, 0.06, 14), 'dirt', x, 0.56, z, { noShadow: true });
    this.roundTree(x, z, 0.8 * s, happy ? 'leaf' : 'leafGray', { col: false, fruit: happy && this.r() < 0.5 ? '#ff9ab8' : null });
    if (happy) this.flowers(x, z, 8, 0.8 * s, ['#ff8ab8', '#ffd24a', '#ffffff']);
  }
  // 運河の小舟
  boat(x, z, ry, col = '#8a5a3a') {
    const y = this.T ? this.T.cap[this.T.at(x, z)] : 0;
    this.mg(col, new THREE.BoxGeometry(1.2, 0.4, 3.2), x, y + 0.05, z, [0, ry, 0]);
    this.mg('wood2', new THREE.BoxGeometry(1.0, 0.1, 0.3), x, y + 0.28, z, [0, ry, 0]);
    const bow = new THREE.ConeGeometry(0.6, 1.0, 4); bow.rotateX(Math.PI / 2); bow.rotateZ(Math.PI / 4);
    this.mg(col, bow, x + Math.sin(ry) * 2.05, y + 0.05, z + Math.cos(ry) * 2.05, [0, ry, 0], [1, 0.5, 1]);
  }
  // 遠景の家（地図の外。当たり判定なし）
  farHouse(x, z, w, d, h, wallC, roofC, y = -1.3) {
    this.mg(wallC, new THREE.BoxGeometry(w, h, d), x, y + h / 2, z);
    const S = Math.min(w, d), L = Math.max(w, d), RH = S * 0.45, tri = new THREE.Shape();
    tri.moveTo(-S / 2 - 0.3, 0); tri.lineTo(0, RH); tri.lineTo(S / 2 + 0.3, 0); tri.closePath();
    const g = new THREE.ExtrudeGeometry(tri, { depth: L + 0.6, bevelEnabled: false }); g.translate(0, 0, -(L + 0.6) / 2);
    this.mg(roofC, g, x, y + h, z, [0, w >= d ? Math.PI / 2 : 0, 0]);
  }
  // 地図の外の家並み（区画の外周の帯に並べる）。skip(x, z)：建てない場所（遠景の城など）
  townBackdrop(o = {}) {
    const Z = this.zone, hw = Z.w / 2, hd = Z.d / 2, r = this.r, band = o.band || 24;
    const walls = o.happy ? ['#fff4e2', '#ffe8d4', '#fde2e8', '#e8f0ff', '#fff2c8'] : ['#c8c4c0', '#bcb8b4', '#d0ccc8'];
    const roofs = o.happy ? ['#e05a4a', '#5a8ad8', '#5aa860', '#f09a4a', '#e87aa8'] : ['#7a7a86', '#8a8a96', '#6e6e7a'];
    for (let x = -hw - band; x <= hw + band; x += 7) for (let z = -hd - band; z <= hd + band; z += 7) {
      const px = x + (r() - 0.5) * 3, pz = z + (r() - 0.5) * 3;
      if (Math.abs(px) < hw + 5 && Math.abs(pz) < hd + 5) continue;
      if (o.skip && o.skip(px, pz)) continue;
      if (r() < 0.15) continue;
      const w = 4 + r() * 3, d = 4 + r() * 3, h = 6 + r() * 7;
      this.farHouse(px, pz, w, d, h, walls[Math.floor(r() * walls.length)], roofs[Math.floor(r() * roofs.length)]);
    }
  }
  // 遠景の城：城壁と、円い塔（とんがり屋根）、まん中の天守
  castleKeep(x, z, o = {}) {
    const y = -1.3, wall = o.happy ? '#f4ece0' : '#c8c4c8', roofs = o.happy ? ['#e87aa8', '#5a8ad8', '#ffd27a'] : ['#8a8a96', '#7a7a86'];
    const s = o.s || 1, W = 34 * s, D = 22 * s;
    this.mg(wall, new THREE.BoxGeometry(W, 12 * s, D), x, y + 6 * s, z);
    for (let i = 0; i < Math.floor(W / 2.4); i++) this.mg(wall, new THREE.BoxGeometry(1.2, 1.2, 1.2), x - W / 2 + 1.2 + i * 2.4, y + 12.6 * s, z + D / 2);
    this.mg(wall, new THREE.BoxGeometry(16 * s, 12 * s, 12 * s), x, y + 18 * s, z - 2 * s);
    const tw = (tx, tz, r0, h, k) => {
      this.mg(wall, new THREE.CylinderGeometry(r0, r0 * 1.08, h, 16), tx, y + h / 2, tz);
      this.mg(roofs[k % roofs.length], new THREE.ConeGeometry(r0 * 1.35, r0 * 2.8, 16), tx, y + h + r0 * 1.4, tz);
      this.mg(o.happy ? this.glow('#ffd8a0', 1.2) : '#6a6a78', new THREE.BoxGeometry(0.8, 1.4, r0 * 2 + 0.1), tx, y + h - 2.5, tz);
    };
    tw(x - W / 2, z + D / 2, 3.2 * s, 20 * s, 0); tw(x + W / 2, z + D / 2, 3.2 * s, 20 * s, 1);
    tw(x - W / 2, z - D / 2, 3 * s, 22 * s, 2); tw(x + W / 2, z - D / 2, 3 * s, 22 * s, 0);
    tw(x - 6 * s, z - 2 * s, 2.6 * s, 30 * s, 1); tw(x + 6 * s, z - 2 * s, 2.6 * s, 30 * s, 2);
    tw(x, z - 4 * s, 3.6 * s, 38 * s, 0);
  }
  // 遠景の笑顔の塔：桃色の円塔に金の帯、てっぺんに星
  smileTower(x, z, o = {}) {
    const y = -1.3, pink = o.happy ? '#f6c6de' : '#b8b0b8', gold = o.happy ? 'gold' : '#8a8a90';
    for (let i = 0; i < 5; i++) { const r0 = 6 - i * 0.7, h = 9; this.mg(pink, new THREE.CylinderGeometry(r0 - 0.3, r0, h, 20), x, y + i * h + h / 2, z); this.mg(gold, new THREE.CylinderGeometry(r0 + 0.1, r0 + 0.1, 0.6, 20), x, y + (i + 1) * h, z); }
    this.mg(o.happy ? '#e87aa8' : '#8a8a96', new THREE.ConeGeometry(3.4, 8, 20), x, y + 49, z);
    this.mg(o.happy ? this.glow('#ffd27a', 2.4) : '#a0a0a8', new THREE.OctahedronGeometry(1.2), x, y + 54, z);
  }
  // ---------------- 仕掛け：影の壁と光の水晶、落石の岩山 ----------------
  // zone.seals：[{ id, wall: [x0, z0, x1, z1], lamps: [[x, z], ...], after, openAfter }]
  //   look: 'memory' ＝ 記憶のかけら（items[i](K, x, y, z) で思い出の品、memories[i] でふれたときにクロが語る台詞）。name・openToast で表示の文言
  //   光の水晶をすべて灯すと、影の壁が消える。after のシーンを見るまでは灯せない。openAfter のシーンを見たあとは、はじめから消えている
  //   灯した水晶と消えた壁は Save.data.flags に残す（id、id_番号）
  seals() {
    const flags = (typeof Save !== 'undefined' && Save.data && Save.data.flags) || {}, kit = this;
    return (this.v.sealObjs = (this.zone.seals || []).map(S => {
      const open = !!flags[S.id] || !!(S.openAfter && storyCond('scene:' + S.openAfter));
      const o = { S, open, lamps: [], ready: () => !S.after || storyCond('scene:' + S.after) };
      // 光の水晶：岩の台座に紫の水晶。灯すと青白く光る。記憶のかけら（look: 'memory'）：石の祭壇に思い出の品と、金色に光る玉
      const mem = S.look === 'memory', litCol = mem ? '#ffe2a8' : '#cfefff', dimCol = mem ? '#b08a50' : '#8a6aff';
      const dim = this.glow(mem ? '#8a6a3a' : '#6a4aa0', 0.7), bright = this.glow(litCol, 3.2);
      S.lamps.forEach(([x, z], i) => {
        const y = this.gy(x, z), lit = open || !!flags[S.id + '_' + i];
        if (mem) { this.box(x, z, 1.1, 0.7, 0.8, 'stone2', { round: true }); if (S.items && S.items[i]) S.items[i](this, x, y + 0.7, z); }
        else this.cyl(x, z, 0.5, 0.8, 'rockDark', { seg: 7, r2: 0.36 });
        const c = this.mesh(mem ? new THREE.SphereGeometry(0.26, 16, 12) : new THREE.OctahedronGeometry(0.34), lit ? bright : dim, x, mem ? 1.7 : 1.3, z, { noShadow: true }); if (!mem) c.scale.y = 1.7;
        const cy = c.position.y - y;
        const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex(), color: hdr(lit ? litCol : dimCol, lit ? 0.9 : 0.35), blending: THREE.AdditiveBlending, depthWrite: false }));
        sp.scale.setScalar(lit ? 3.4 : 1.6); sp.position.set(x, y + cy, z); this.scene.add(sp);
        const L = { i, pos: V3(x, y, z), lit, c, sp, setLit() { L.lit = true; c.material = bright; sp.material.color.copy(hdr(litCol, 0.9)); sp.scale.setScalar(3.4); } };
        const ph = this.r() * 6; this.tick((dt, t) => { c.rotation.y += dt * (L.lit ? 1.2 : 0.3); c.position.y = y + cy + Math.sin(t * 1.6 + ph) * 0.05; sp.position.y = c.position.y; if (!L.lit) sp.material.opacity = 0.6 + Math.sin(t * 2 + ph) * 0.3; });
        o.lamps.push(L);
      });
      if (open) return o;
      // 影の壁：闇がうずまく半透明の面（三枚重ね）と、通れない当たり判定
      const [x0, z0, x1, z1] = S.wall, cx = (x0 + x1) / 2, cz = (z0 + z1) / 2, w = Math.abs(x1 - x0), d = Math.abs(z1 - z0), y = this.gy(cx, cz), h = 5, len = Math.max(w, d);
      const g = new THREE.Group(); g.position.set(cx, y, cz); g.rotation.y = w >= d ? 0 : Math.PI / 2; this.scene.add(g);
      const mats = [0, 1, 2].map(k => { const t = shadowWallTex().clone(); t.needsUpdate = true; t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(len / 3, 1.6);
        return new THREE.MeshBasicMaterial({ map: t, color: k === 1 ? '#140820' : hdr('#9a6aff', 0.8), transparent: true, opacity: k === 1 ? 0.88 : 0.4, blending: k === 1 ? THREE.NormalBlending : THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false }); });
      mats.forEach((m, k) => { const pl = new THREE.Mesh(new THREE.PlaneGeometry(len, h), m); pl.position.set(0, h / 2, (k - 1) * 0.3); pl.renderOrder = 3; g.add(pl); });
      o.col = { box: true, x: cx, z: cz, hw: Math.max(w / 2, 0.35), hd: Math.max(d / 2, 0.35), top: h, y };
      this.v.colliders.push(o.col);
      let fade = 1;
      this.tick((dt, t) => {
        if (!g.parent) return;
        mats.forEach((m, k) => { m.map.offset.x = t * (k - 1) * 0.08; m.map.offset.y = -t * 0.12 * (k + 1); });
        if (o.open) { fade -= dt * 0.8; if (fade <= 0) { g.removeFromParent(); return; } }
        mats.forEach((m, k) => { m.opacity = (k === 1 ? 0.88 : 0.4 + Math.sin(t * 2 + k) * 0.1) * fade; });
        if (kit.v.p && Math.random() < dt * 10 * fade) kit.v.p.emit(V3(cx + (Math.random() - 0.5) * w, y + Math.random() * h, cz + (Math.random() - 0.5) * d), V3(0, 0.6, 0), hdr(Math.random() < 0.5 ? '#8a5aff' : '#2a1040', 1.4), { life: 1.6, size: 0.12, drag: 0.5 });
      });
      o.dissolve = () => { o.open = true; const i = kit.v.colliders.indexOf(o.col); if (i >= 0) kit.v.colliders.splice(i, 1); };
      return o;
    }));
  }
  // zone.rubble：[{ id, at: [x, z], r }]：攻撃で砕ける落石の岩山（砕いたら Save.data.flags[id]）
  rubbles() {
    const flags = (typeof Save !== 'undefined' && Save.data && Save.data.flags) || {};
    return (this.v.rubbleObjs = (this.zone.rubble || []).map(R => {
      const [x, z] = R.at, r0 = R.r || 1.6, o = { R, pos: V3(x, this.gy(x, z), z), broken: !!flags[R.id] };
      if (o.broken) return o;
      const g = new THREE.Group(); g.position.copy(o.pos); this.scene.add(g);
      for (let i = 0; i < 8; i++) { const s = 0.45 + this.r() * 0.55, m = new THREE.Mesh(new THREE.DodecahedronGeometry(s, 0), this.mat(i % 3 ? 'rockDark' : 'rock')); m.position.set((this.r() - 0.5) * r0 * 1.5, s * 0.55 + (i > 5 ? 0.8 : 0), (this.r() - 0.5) * r0 * 0.9); m.rotation.set(this.r() * 3, this.r() * 3, 0); m.castShadow = true; g.add(m); }
      o.g = g; o.col = { x, z, r: r0, top: 2, y: o.pos.y }; this.v.colliders.push(o.col);
      return o;
    }));
  }
  // ---------------- 自然 ----------------
  roundTree(x, z, s = 1, leaf = 'leaf', o = {}) {
    this.cyl(x, z, 0.22 * s, 1.8 * s, 'bark', { r2: 0.16 * s, seg: 7, col: o.col });
    const n = o.lush ? 5 : 3;
    for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2 + this.r(); const m = this.mesh(new THREE.IcosahedronGeometry((0.9 + this.r() * 0.3) * s, 1), leaf, x + Math.cos(a) * 0.55 * s, (2.2 + this.r() * 0.5) * s, z + Math.sin(a) * 0.55 * s); m.scale.y = 0.85; }
    this.mesh(new THREE.IcosahedronGeometry(1.05 * s, 1), leaf, x, 2.8 * s, z).scale.y = 0.9;
    if (o.fruit) for (let i = 0; i < 4; i++) { const a = this.r() * 6; this.mesh(new THREE.SphereGeometry(0.12 * s, 8, 6), this.glow(o.fruit, 1.4), x + Math.cos(a) * 0.9 * s, (2.4 + this.r() * 0.6) * s, z + Math.sin(a) * 0.9 * s, { noShadow: true }); }
  }
  pine(x, z, s = 1, leaf = 'leafDark') {
    this.cyl(x, z, 0.2 * s, 1.2 * s, 'bark', { seg: 7 });
    for (let i = 0; i < 3; i++) this.mesh(new THREE.ConeGeometry((1.4 - i * 0.36) * s, 1.6 * s, 8), leaf, x, (1.5 + i * 0.95) * s, z);
  }
  deadTree(x, z, s = 1) {
    this.cyl(x, z, 0.2 * s, 2.6 * s, 'bark', { r2: 0.1 * s, seg: 6 });
    for (let i = 0; i < 4; i++) this.mesh(new THREE.CylinderGeometry(0.03 * s, 0.08 * s, 1.3 * s, 5), 'bark', x, (1.6 + i * 0.25) * s, z, { rz: (i % 2 ? 1 : -1) * (0.6 + this.r() * 0.4), ry: i * 1.6 });
  }
  bush(x, z, s = 1, leaf = 'leaf2', flower) {
    for (let i = 0; i < 3; i++) { const m = this.mesh(new THREE.IcosahedronGeometry(0.55 * s, 1), leaf, x + (i - 1) * 0.45 * s, 0.35 * s, z + (this.r() - 0.5) * 0.4 * s); m.scale.y = 0.75; }
    if (flower) for (let i = 0; i < 4; i++) this.mesh(new THREE.SphereGeometry(0.09 * s, 6, 4), flower, x + (this.r() - 0.5) * 1.2 * s, 0.62 * s, z + (this.r() - 0.5) * 0.6 * s, { noShadow: true });
    this.col(x, z, 0.8 * s, 0.8 * s);
  }
  flowers(x, z, n = 10, r = 2, cols = ['#ffffff', '#ffe07a', '#ffb8d8', '#b8d8ff']) {
    const stem = this.batch('leaf2');
    for (let i = 0; i < n; i++) {
      const a = this.r() * Math.PI * 2, d = Math.sqrt(this.r()) * r, px = x + Math.cos(a) * d, pz = z + Math.sin(a) * d, y = this.gy(px, pz), h = 0.25 + this.r() * 0.2;
      stem.box(px - 0.015, y, pz - 0.015, px + 0.015, y + h, pz + 0.015);
      this.batch(cols[i % cols.length]).box(px - 0.08, y + h, pz - 0.08, px + 0.08, y + h + 0.06, pz + 0.08, '');
    }
  }
  rock(x, z, s = 1, mat = 'rock') { const m = this.mesh(new THREE.DodecahedronGeometry(s, 0), mat, x, s * 0.45, z, { ry: this.r() * 3 }); m.scale.y = 0.7; this.col(x, z, s * 0.9, s); return m; }
  mushroom(x, z, s = 1, cap = '#e05a6a', glowCol) {
    this.cyl(x, z, 0.12 * s, 0.6 * s, 'cream', { col: s > 1.5, seg: 8 });
    const m = this.mesh(new THREE.SphereGeometry(0.4 * s, 14, 8, 0, Math.PI * 2, 0, Math.PI / 2), glowCol ? this.glow(glowCol, 1.2) : cap, x, 0.55 * s, z); m.scale.y = 0.7;
    if (!glowCol) for (let i = 0; i < 3; i++) { const a = i * 2.1; this.mesh(new THREE.SphereGeometry(0.06 * s, 6, 4), 'white', x + Math.cos(a) * 0.22 * s, 0.75 * s, z + Math.sin(a) * 0.22 * s, { noShadow: true }); }
  }
  log(x, z, len = 3, ry = 0) { this.mesh(new THREE.CylinderGeometry(0.35, 0.38, len, 10), 'bark', x, 0.35, z, { rz: Math.PI / 2, ry }); this.col(x, z, len * 0.4, 0.7); }
  water(x, z, w, d, o = {}) {
    const m = this.mesh(new THREE.PlaneGeometry(w, d), new THREE.MeshStandardMaterial({ color: o.col || '#6ac0f0', transparent: true, opacity: 0.8, roughness: 0.1, metalness: 0.2, emissive: o.col || '#3a90d0', emissiveIntensity: 0.25 }), x, 0.04, z, { rx: -Math.PI / 2, rz: o.ry || 0, noShadow: true });
    m.receiveShadow = false;
    const y0 = m.position.y; this.tick((dt, t) => { m.material.emissiveIntensity = 0.22 + Math.sin(t * 1.5 + x) * 0.05; m.position.y = y0 + Math.sin(t) * 0.01; });
    return m;
  }
  pond(x, z, r = 3) {
    const m = this.mesh(new THREE.CircleGeometry(r, 32), new THREE.MeshStandardMaterial({ color: '#6ac0f0', transparent: true, opacity: 0.82, roughness: 0.08, metalness: 0.2, emissive: '#3a90d0', emissiveIntensity: 0.25 }), x, 0.05, z, { rx: -Math.PI / 2, noShadow: true });
    for (let i = 0; i < 10; i++) { const a = i / 10 * Math.PI * 2; this.rock(x + Math.cos(a) * (r + 0.3), z + Math.sin(a) * (r + 0.3), 0.35 + this.r() * 0.25); }
    this.col(x, z, r * 0.9, 0.3);
    return m;
  }
  bridge(x, z, len, ry = 0, w = 2.4) {
    const g = new THREE.Group(); g.position.set(x, this.gy(x, z), z); g.rotation.y = ry; this.scene.add(g);
    for (let i = 0; i < Math.ceil(len / 0.5); i++) { const p = new THREE.Mesh(new THREE.BoxGeometry(w, 0.1, 0.44), this.mat(i % 2 ? 'wood' : 'wood2')); p.position.set(0, 0.25 + Math.sin(i / (len / 0.5) * Math.PI) * 0.35, -len / 2 + i * 0.5); p.castShadow = true; p.receiveShadow = true; g.add(p); }
    for (const s of [-1, 1]) { const rail = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.1, len), this.mat('wood2')); rail.position.set(s * w / 2, 0.95, 0); g.add(rail); for (let i = 0; i <= 4; i++) { const post = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.8, 0.12), this.mat('wood2')); post.position.set(s * w / 2, 0.5, -len / 2 + i * len / 4); g.add(post); } }
  }

  // ---------------- 村の建物 ----------------
  // にゃんこの家：クリーム色の壁、三角屋根の端に猫耳、丸い扉。face = 玄関の向き
  catHouse(x, z, w, d, h, face, o = {}) {
    const side = face === 'e' || face === 'w', f = { n: [0, -1], s: [0, 1], e: [1, 0], w: [-1, 0] }[face];
    const W = side ? d : w, D = side ? w : d, faceRy = Math.atan2(f[0], f[1]);
    this.box(x, z, w, h, d, o.wall || (this.r() < 0.5 ? 'plaster' : 'plaster2'));
    // 木の柱（角）
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) this.mesh(new THREE.BoxGeometry(0.25, h, 0.25), 'wood2', x + sx * (w / 2 - 0.05), h / 2, z + sz * (d / 2 - 0.05));
    // 切妻屋根（棟は玄関の向きと直交）
    const roofM = o.roof || pick(['roofRed', 'roofBlue', 'roofGreen', 'roofOrange']);
    const RL = W + 0.8, RD = D / 2 + 0.6, RH = Math.min(2.4, D * 0.5);
    const shape = new THREE.Shape(); shape.moveTo(-RD, 0); shape.lineTo(0, RH); shape.lineTo(RD, 0); shape.lineTo(RD, -0.25); shape.lineTo(0, RH - 0.3); shape.lineTo(-RD, -0.25); shape.closePath();
    const rg = new THREE.ExtrudeGeometry(shape, { depth: RL, bevelEnabled: false }); rg.translate(0, 0, -RL / 2);
    const roof = this.mesh(rg, roofM, x, h, z, { ry: faceRy + Math.PI / 2 });
    // 妻壁（三角）
    const gs = new THREE.Shape(); gs.moveTo(-D / 2, 0); gs.lineTo(0, RH - 0.3); gs.lineTo(D / 2, 0); gs.closePath();
    for (const s of [-1, 1]) this.mesh(new THREE.ShapeGeometry(gs), o.wall || 'plaster', x + (side ? 0 : s * w / 2 * 1.001), h, z + (side ? s * d / 2 * 1.001 : 0), { ry: faceRy + Math.PI / 2 + (s > 0 ? 0 : Math.PI) }).material.side = THREE.DoubleSide;
    // 棟の両端の猫耳
    const ridgeDir = V3(Math.cos(faceRy), 0, -Math.sin(faceRy));
    for (const s of [-1, 1]) { const eg = new THREE.ConeGeometry(0.35, 0.6, 4); eg.rotateY(Math.PI / 4); const e = this.mesh(eg, roofM, x + ridgeDir.x * s * (RL / 2 - 0.4), h + RH + 0.15, z + ridgeDir.z * s * (RL / 2 - 0.4), { ry: faceRy }); e.scale.z = 0.5; }
    // 丸い扉と窓
    const at = (u, y, off = 0.03) => [x + f[0] * (D / 2 + off) + (side ? 0 : u), y, z + f[1] * (D / 2 + off) + (side ? u : 0)];
    const door = new THREE.Shape(); door.moveTo(-0.55, 0); door.lineTo(-0.55, 1.2); door.absarc(0, 1.2, 0.55, Math.PI, 0, true); door.lineTo(0.55, 0); door.closePath();
    this.mesh(new THREE.ShapeGeometry(door), 'wood2', ...at(o.doorU || 0, 0.02), { ry: faceRy, noShadow: true });
    this.mesh(new THREE.CircleGeometry(0.07, 10), 'gold', ...at((o.doorU || 0) + 0.3, 0.9, 0.05), { ry: faceRy, noShadow: true });
    if (W > 3.6) for (const u of [-W / 2 + 0.9, W / 2 - 0.9]) { if (Math.abs(u - (o.doorU || 0)) < 1.2) continue; this.mesh(new THREE.CircleGeometry(0.42, 16), this.glow(o.lit ? '#ffd27a' : '#bfe8ff', o.lit ? 1.6 : 0.6), ...at(u, Math.min(1.7, h - 0.8)), { ry: faceRy, noShadow: true }); this.mesh(new THREE.TorusGeometry(0.44, 0.05, 6, 20), 'wood2', ...at(u, Math.min(1.7, h - 0.8), 0.05), { ry: faceRy }); }
    // 煙突
    if (o.chimney !== false) { this.mesh(new THREE.BoxGeometry(0.5, 1.4, 0.5), 'stone', x - ridgeDir.x * W * 0.25, h + RH * 0.6 + 0.4, z - ridgeDir.z * W * 0.25); if (o.smoke) this.smoke(x - ridgeDir.x * W * 0.25, h + RH * 0.6 + 1.2, z - ridgeDir.z * W * 0.25, '#e8e0d8', 2); }
    // 看板
    if (o.sign) this.sign(...at(0, h - 0.35, 0.3).filter((_, i) => i !== 1), faceRy, o.sign, o.sub, o.signCol || '#ffd27a', h + 0.35 + RH * 0.1, Math.min(3.4, W - 0.4));
    this.reserve(x, z, Math.max(w, d) / 2 + 1);
    return { at, faceRy };
  }
  sign(x, z, ry, text, sub, col = '#ffd27a', y = 3.6, w = 3.2) {
    return this.mesh(new THREE.PlaneGeometry(w, w / 4), new THREE.MeshBasicMaterial({ map: signTex(text, sub, col), transparent: true, toneMapped: false, side: THREE.DoubleSide }), x, y, z, { ry, noShadow: true });
  }
  signpost(x, z, ry, text, sub) {
    this.box(x, z, 0.18, 2.2, 0.18, 'wood2');
    this.sign(x + Math.sin(ry) * 0.12, z + Math.cos(ry) * 0.12, ry, text, sub, '#ffd27a', 1.8, 2.0);
  }
  // 看板：二本の脚に横長の札（ry = 札の正面）
  board(x, z, ry, text, sub) {
    const c = Math.cos(ry), sn = Math.sin(ry);
    for (const u of [-0.9, 0.9]) this.cyl(x + u * c, z - u * sn, 0.07, 1.9, 'wood2', { seg: 6 });
    this.box(x, z, 2.2, 0.62, 0.1, 'wood2', { y: 1.15, ry, col: false });
    this.sign(x + sn * 0.06, z + c * 0.06, ry, text, sub, '#ffd27a', 1.46, 2.1);
  }
  // 壁の貼り紙（ry = 紙の正面。壁の面のすぐ手前に置く）。o.bg／o.ink：紙と字の色、o.stain：涙のしみ
  paper(x, z, ry, title, lines = [], o = {}) {
    const c = document.createElement('canvas'); c.width = 256; c.height = 340;
    const g = c.getContext('2d'), ink = o.ink || '#4a3a2a';
    g.fillStyle = o.bg || '#f4ecd8'; g.fillRect(0, 0, 256, 340);
    g.strokeStyle = ink; g.globalAlpha = 0.5; g.lineWidth = 6; g.strokeRect(10, 10, 236, 320); g.globalAlpha = 1;
    g.fillStyle = ink; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.font = '900 34px "Hiragino Maru Gothic ProN","Hiragino Sans",sans-serif'; g.fillText(title, 128, 60, 220);
    g.font = '800 24px "Hiragino Maru Gothic ProN","Hiragino Sans",sans-serif';
    lines.forEach((l, i) => g.fillText(l, 128, 130 + i * 42, 220));
    if (o.stain) for (let i = 0; i < 5; i++) { g.fillStyle = 'rgba(90,110,150,.22)'; g.beginPath(); g.ellipse(70 + i * 30, 200 + (i % 2) * 40, 10, 22, 0, 0, Math.PI * 2); g.fill(); }
    const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace;
    const w = o.w || 1.1;
    return this.mesh(new THREE.PlaneGeometry(w, w * 340 / 256), new THREE.MeshStandardMaterial({ map: t, roughness: 0.9 }), x, o.y || 1.7, z, { ry, noShadow: true });
  }
  // 壁のひっかき傷：四本の爪あと（ry = 壁の正面。岩肌の凹凸に埋もれないよう、壁の前後に厚みをもたせる）
  scratches(x, z, ry, y = 1.5, col = '#d8c8f0') {
    for (let i = 0; i < 4; i++) { const u = (i - 1.5) * 0.24; this.mesh(new THREE.BoxGeometry(0.07, 0.9, 1.0), this.glow(col, 0.9), x + Math.cos(ry) * u, y, z - Math.sin(ry) * u, { ry, rz: 0.25, noShadow: true }); }
  }
  stall(x, z, ry = 0, cloth = 'clothRed', goods = ['#ffd27a', '#ff8a5a', '#6dff9e']) {
    this.box(x, z, 2.8, 1, 1.4, 'wood', { ry });
    const c = Math.cos(ry), sn = Math.sin(ry), P = (u, v) => [x + u * c + v * sn, z - u * sn + v * c];
    for (const u of [-1.3, 1.3]) for (const v of [-0.6, 0.6]) { const [px, pz] = P(u, v); this.mesh(new THREE.BoxGeometry(0.08, 2.3, 0.08), 'wood2', px, 1.15, pz); }
    const aw = this.mesh(new THREE.BoxGeometry(3.2, 0.1, 1.9), cloth, x, 2.35, z, { ry }); aw.rotateX(0.18);
    for (let i = 0; i < 5; i++) { const [px, pz] = P(-1 + i * 0.5, 0); this.mesh(new THREE.SphereGeometry(0.16, 8, 6), goods[i % goods.length], px, 1.15, pz); }
  }
  // 魚を干す棚
  fishRack(x, z, ry = 0) {
    const c = Math.cos(ry), sn = Math.sin(ry);
    for (const u of [-1.2, 1.2]) this.box(x + u * c, z - u * sn, 0.12, 1.9, 0.12, 'wood2', { col: false });
    this.mesh(new THREE.BoxGeometry(2.6, 0.08, 0.08), 'wood2', x, 1.8, z, { ry });
    for (let i = 0; i < 5; i++) { const u = -1 + i * 0.5, f = this.mesh(new THREE.SphereGeometry(0.14, 10, 8), i % 2 ? '#8ab8d8' : '#b8c8d8', x + u * c, 1.4, z - u * sn); f.scale.set(0.5, 2.2, 0.8); this.mesh(new THREE.ConeGeometry(0.12, 0.18, 3), '#8ab8d8', x + u * c, 1.0, z - u * sn, { rx: Math.PI }).scale.z = 0.3; }
    this.col(x, z, 1.4, 1.9);
  }
  well(x, z) {
    this.cyl(x, z, 1.0, 0.9, 'stone', { seg: 14 });
    this.mesh(new THREE.CircleGeometry(0.85, 20), new THREE.MeshStandardMaterial({ color: '#3a7aaa', roughness: 0.1, emissive: '#1a4a7a', emissiveIntensity: 0.3 }), x, 0.85, z, { rx: -Math.PI / 2, noShadow: true });
    for (const s of [-1, 1]) this.box(x + s * 0.85, z, 0.14, 2.2, 0.14, 'wood2', { y: 0.9, col: false });
    this.mesh(new THREE.ConeGeometry(1.4, 0.8, 4), 'roofRed', x, 3.4, z, { ry: Math.PI / 4 });
    this.mesh(new THREE.CylinderGeometry(0.2, 0.18, 0.3, 10), 'wood', x, 2.2, z);
  }
  fountain(x, z, dry = false) {
    this.cyl(x, z, 2.4, 0.6, 'stone', { seg: 24 });
    this.cyl(x, z, 0.4, 1.8, 'stone2', { seg: 10, col: false });
    this.mesh(new THREE.CylinderGeometry(0.9, 0.5, 0.3, 16), 'stone', x, 1.8, z);
    if (!dry) {
      this.mesh(new THREE.CircleGeometry(2.2, 24), new THREE.MeshStandardMaterial({ color: '#7ad0f8', transparent: true, opacity: 0.8, roughness: 0.05, emissive: '#3a90d0', emissiveIntensity: 0.3 }), x, 0.55, z, { rx: -Math.PI / 2, noShadow: true });
      this.v.emitters.push(dt => { for (let i = 0; i < 20 * dt; i++) this.v.p.emit(V3(x, 2.0 + this.gy(x, z), z), V3((Math.random() - 0.5) * 1.2, 2 + Math.random(), (Math.random() - 0.5) * 1.2), hdr('#bfe8ff', 1.4), { life: 0.9, size: 0.07, grav: 6, drag: 0.2 }); });
    }
  }
  bench(x, z, ry = 0) { this.box(x, z, 2, 0.12, 0.6, 'wood', { y: 0.45, ry, col: false }); this.box(x, z, 1.8, 0.45, 0.4, 'wood2', { ry }); }
  barrel(x, z) { this.cyl(x, z, 0.45, 1.1, 'wood', { seg: 12 }); for (const y of [0.2, 0.9]) this.mesh(new THREE.TorusGeometry(0.46, 0.03, 4, 16), 'iron', x, y, z, { rx: Math.PI / 2 }); }
  crate(x, z, s = 1.1) { this.box(x, z, s, s, s, 'wood', { round: true, ry: this.r() < 0.5 ? 0 : Math.PI / 2 }); }
  lantern(x, z, col = '#ffb04a', h = 2.6) {
    this.box(x, z, 0.18, h, 0.18, 'wood2');
    this.mesh(new THREE.BoxGeometry(0.7, 0.1, 0.1), 'wood2', x + 0.3, h - 0.1, z);
    this.mesh(new THREE.BoxGeometry(0.28, 0.36, 0.28), this.glow(col, 2.2), x + 0.55, h - 0.45, z, { noShadow: true });
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex(), color: hdr(col, 0.5), blending: THREE.AdditiveBlending, depthWrite: false }));
    sp.scale.setScalar(1.8); sp.position.set(x + 0.55, h - 0.45 + this.gy(x, z), z); this.scene.add(sp);
  }
  stoneLantern(x, z, col = '#ffb04a') {
    this.box(x, z, 0.9, 0.3, 0.9, 'stone');
    this.cyl(x, z, 0.18, 1.1, 'stone', { y: 0.3, r2: 0.15, col: false, seg: 8 });
    this.box(x, z, 0.7, 0.5, 0.7, 'stone', { y: 1.4, col: false });
    this.mesh(new THREE.BoxGeometry(0.5, 0.3, 0.72), this.glow(col, 2.2), x, 1.65, z, { noShadow: true });
    this.mesh(new THREE.ConeGeometry(0.65, 0.45, 4), 'stone', x, 2.1, z, { ry: Math.PI / 4 });
  }
  brazier(x, z, col = '#ff9a3a', h = 1.3) { this.cyl(x, z, 0.22, h, 'iron', { seg: 8 }); this.mesh(new THREE.CylinderGeometry(0.7, 0.35, 0.45, 12), 'gold', x, h + 0.2, z); this.fire(x, h + 0.45, z, col, 26, 0.28); }
  fire(x, y, z, col = '#ff8a3a', rate = 30, size = 0.25) {
    y += this.gy(x, z);
    this.v.emitters.push(dt => { for (let i = 0; i < rate * dt; i++) this.v.p.emit(V3(x + (Math.random() - 0.5) * 0.4, y, z + (Math.random() - 0.5) * 0.4), V3((Math.random() - 0.5) * 0.3, 1.4 + Math.random(), (Math.random() - 0.5) * 0.3), hdr(col, 2.2), { life: 0.6, size, drag: 1 }); });
  }
  smoke(x, y, z, col = '#c8c8d8', rate = 6) {
    y += this.gy(x, z);
    this.v.emitters.push(dt => { for (let i = 0; i < rate * dt; i++) this.v.p.emit(V3(x + (Math.random() - 0.5) * 0.6, y, z + (Math.random() - 0.5) * 0.6), V3(0, 0.8 + Math.random() * 0.5, 0), hdr(col, 0.35), { life: 2.2, size: 0.6, drag: 0.3 }); });
  }
  campfire(x, z) {
    for (let i = 0; i < 6; i++) { const a = i / 6 * Math.PI * 2; this.mesh(new THREE.DodecahedronGeometry(0.22, 0), 'rock', x + Math.cos(a) * 0.6, 0.12, z + Math.sin(a) * 0.6); }
    for (let i = 0; i < 3; i++) this.mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.9, 6), 'bark', x, 0.18, z, { rz: Math.PI / 2, ry: i * 1.05 });
    this.fire(x, 0.3, z, '#ff9a3a', 30, 0.26); this.col(x, z, 0.8, 0.5);
    this.light(x, 1.2, z, '#ffb060', 10, 12);
  }
  tent(x, z, ry = 0, cloth = 'clothYellow') {
    const g = new THREE.ConeGeometry(1.8, 2.2, 4); g.rotateY(Math.PI / 4);
    const m = this.mesh(g, cloth, x, 1.1, z, { ry }); m.scale.set(1, 1, 1.4);
    this.mesh(new THREE.PlaneGeometry(0.9, 1.3), 'wood2', x + Math.sin(ry) * 1.29, 0.65, z + Math.cos(ry) * 1.29, { ry, noShadow: true });
    this.col(x, z, 1.7, 2.2);
  }
  windmill(x, z, s = 1) {
    this.cyl(x, z, 1.4 * s, 6 * s, 'plaster', { r2: 1 * s, seg: 10 });
    this.mesh(new THREE.ConeGeometry(1.4 * s, 1.8 * s, 10), 'roofRed', x, 6.9 * s, z);
    const hub = new THREE.Group(); hub.position.set(x, 5.4 * s + this.gy(x, z), z + 1.2 * s); this.scene.add(hub);
    for (let i = 0; i < 4; i++) { const b = new THREE.Mesh(new THREE.BoxGeometry(0.6 * s, 3.4 * s, 0.06), this.mat('clothWhite')); b.position.y = 1.8 * s; const p = new THREE.Group(); p.rotation.z = i * Math.PI / 2; p.add(b); hub.add(p); b.castShadow = true; }
    this.tick(dt => { hub.rotation.z += dt * 0.6; });
  }
  // 神社：朱い鳥居と小さな社
  torii(x, z, ry = 0, s = 1) {
    const c = Math.cos(ry), sn = Math.sin(ry);
    for (const u of [-1.4, 1.4]) this.cyl(x + u * c * s, z - u * sn * s, 0.16 * s, 3.4 * s, 'red', { seg: 10 });
    this.mesh(new THREE.BoxGeometry(4.2 * s, 0.25 * s, 0.35 * s), 'red', x, 3.5 * s, z, { ry });
    this.mesh(new THREE.BoxGeometry(3.4 * s, 0.18 * s, 0.25 * s), 'red', x, 2.9 * s, z, { ry });
    this.mesh(new THREE.BoxGeometry(4.6 * s, 0.14 * s, 0.4 * s), '#2a2a34', x, 3.68 * s, z, { ry });
  }
  shrine(x, z, ry = 0) {
    this.box(x, z, 4.4, 0.6, 3.6, 'stone', { ry });
    this.box(x, z, 3.2, 2.4, 2.4, 'wood', { ry, y: 0.6 });
    const g = new THREE.ConeGeometry(3.1, 1.6, 4); g.rotateY(Math.PI / 4);
    const r = this.mesh(g, '#3a3a4a', x, 3.8, z, { ry }); r.scale.set(1.2, 1, 0.9);
    this.mesh(new THREE.BoxGeometry(1.6, 0.5, 0.1), 'gold', x + Math.sin(ry) * 1.25, 2.6, z + Math.cos(ry) * 1.25, { ry, noShadow: true });
    this.mesh(new THREE.SphereGeometry(0.22, 12, 10), 'gold', x + Math.sin(ry) * 1.35, 2.0, z + Math.cos(ry) * 1.35);
    this.catStatue(x + Math.sin(ry) * 2.6 + Math.cos(ry) * 1.6, z + Math.cos(ry) * 2.6 - Math.sin(ry) * 1.6, ry, 0.8);
    this.catStatue(x + Math.sin(ry) * 2.6 - Math.cos(ry) * 1.6, z + Math.cos(ry) * 2.6 + Math.sin(ry) * 1.6, ry, 0.8);
  }
  // 猫の石像（台座つき）
  catStatue(x, z, ry = 0, s = 1, mat = 'stone', eye) {
    this.box(x, z, 1.1 * s, 0.5 * s, 1.1 * s, 'stone2', { ry });
    const b = this.mesh(new THREE.SphereGeometry(0.42 * s, 14, 10), mat, x, 0.95 * s, z); b.scale.set(1, 1.15, 0.9);
    this.mesh(new THREE.SphereGeometry(0.4 * s, 14, 10), mat, x, 1.65 * s, z).scale.set(1.15, 0.95, 1);
    for (const sd of [-1, 1]) { const eg = new THREE.ConeGeometry(0.13 * s, 0.26 * s, 4); eg.rotateY(Math.PI / 4); const e = this.mesh(eg, mat, x + Math.cos(ry) * sd * 0.24 * s, 2.0 * s, z - Math.sin(ry) * sd * 0.24 * s, { ry }); e.scale.z = 0.5; e.rotation.z = -sd * 0.35; }
    if (eye) for (const sd of [-1, 1]) this.mesh(new THREE.SphereGeometry(0.05 * s, 8, 6), this.glow(eye, 3), x + Math.cos(ry) * sd * 0.14 * s + Math.sin(ry) * 0.36 * s, 1.68 * s, z - Math.sin(ry) * sd * 0.14 * s + Math.cos(ry) * 0.36 * s, { noShadow: true });
  }
  // お地蔵さまならぬ、ねこ地蔵（ここで休める）
  grave(x, z, ry = 0, name, flowerCol = '#ffffff') {
    this.box(x, z, 0.8, 1.1, 0.3, 'stone', { ry, round: true });
    this.mesh(new THREE.SphereGeometry(0.4, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2), 'stone', x, 1.1, z, { ry }).scale.z = 0.38;
    if (name) this.sign(x + Math.sin(ry) * 0.17, z + Math.cos(ry) * 0.17, ry, name, null, '#c8a8ff', 0.7, 0.72);
    this.flowers(x + Math.sin(ry) * 0.5, z + Math.cos(ry) * 0.5, 4, 0.3, [flowerCol]);
  }
  crater(x, z, r = 5) {
    const m = this.mesh(new THREE.TorusGeometry(r, r * 0.22, 10, 36), 'dirt', x, 0, z, { rx: Math.PI / 2 }); m.scale.z = 0.35;
    this.mesh(new THREE.CircleGeometry(r * 0.95, 32), new THREE.MeshStandardMaterial({ color: '#5a4a38', roughness: 1 }), x, 0.03, z, { rx: -Math.PI / 2, noShadow: true });
    for (let i = 0; i < 14; i++) { const a = this.r() * Math.PI * 2, d = r * (1.2 + this.r() * 0.6); this.mesh(new THREE.DodecahedronGeometry(0.2 + this.r() * 0.3, 0), 'rockDark', x + Math.cos(a) * d, 0.1, z + Math.sin(a) * d); }
  }
  // 友情の実のかけら（流れ星に見えた、樹から落ちた実の残り）
  starRock(x, z, s = 1, col = '#fff0a8') {
    const m = this.mesh(new THREE.OctahedronGeometry(0.6 * s, 0), new THREE.MeshStandardMaterial({ color: '#fff8e0', emissive: col, emissiveIntensity: 1.2, roughness: 0.3, flatShading: true }), x, 0.5 * s, z, { ry: 0.4 });
    m.scale.y = 1.3;
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex(), color: hdr(col, 0.8), blending: THREE.AdditiveBlending, depthWrite: false })); sp.scale.setScalar(3 * s); sp.position.copy(m.position); this.scene.add(sp);
    this.tick((dt, t) => { m.rotation.y += dt * 0.3; sp.material.opacity = 0.7 + Math.sin(t * 3) * 0.3; });
    this.col(x, z, 0.8 * s, 1.2 * s);
    return m;
  }
  // 巨木（ほしふる森）
  bigTree(x, z, s = 1, leaf = 'leaf2', glowFruit) {
    this.cyl(x, z, 1.4 * s, 7 * s, 'bark', { r2: 0.9 * s, seg: 12 });
    for (let i = 0; i < 5; i++) { const a = i / 5 * Math.PI * 2; const rt = this.mesh(new THREE.ConeGeometry(0.5 * s, 2.6 * s, 6), 'bark', x + Math.cos(a) * 1.4 * s, 0.6 * s, z + Math.sin(a) * 1.4 * s, { rz: Math.cos(a) * 0.9, rx: -Math.sin(a) * 0.9 }); }
    for (let i = 0; i < 7; i++) { const a = i / 7 * Math.PI * 2 + 0.3; const m = this.mesh(new THREE.IcosahedronGeometry((2.2 + this.r()) * s, 1), leaf, x + Math.cos(a) * 2.3 * s, (7.5 + this.r() * 1.5) * s, z + Math.sin(a) * 2.3 * s); m.scale.y = 0.75; }
    this.mesh(new THREE.IcosahedronGeometry(3 * s, 1), leaf, x, 9.5 * s, z).scale.y = 0.8;
    if (glowFruit) for (let i = 0; i < 8; i++) { const a = this.r() * 6; this.mesh(new THREE.SphereGeometry(0.2 * s, 8, 6), this.glow(glowFruit, 1.8), x + Math.cos(a) * 3 * s, (6.5 + this.r() * 2) * s, z + Math.sin(a) * 3 * s, { noShadow: true }); }
    this.col(x, z, 1.6 * s, 7 * s);
  }
  // 小さなネズミの家（どんぐり型）
  ratHouse(x, z, s = 1, ry = 0) {
    const b = this.mesh(new THREE.SphereGeometry(0.8 * s, 14, 10), 'wood', x, 0.7 * s, z); b.scale.y = 1.1;
    const cap = this.mesh(new THREE.SphereGeometry(0.88 * s, 14, 8, 0, Math.PI * 2, 0, Math.PI / 2), 'bark', x, 1.1 * s, z); cap.scale.y = 0.6;
    this.mesh(new THREE.CylinderGeometry(0.06 * s, 0.06 * s, 0.35 * s, 6), 'bark', x, 1.7 * s, z);
    this.mesh(new THREE.CircleGeometry(0.28 * s, 14), 'wood2', x + Math.sin(ry) * 0.79 * s, 0.4 * s, z + Math.cos(ry) * 0.79 * s, { ry, noShadow: true });
    this.col(x, z, 0.9 * s, 1.8 * s);
  }
  cheese(x, z, s = 1) {
    const g = new THREE.CylinderGeometry(0.8 * s, 0.8 * s, 0.6 * s, 3, 1); const m = this.mesh(g, 'cheese', x, 0.3 * s, z, { ry: this.r() * 3 });
    for (let i = 0; i < 3; i++) this.mesh(new THREE.SphereGeometry(0.1 * s, 6, 4), '#e8b830', x + (this.r() - 0.5) * 0.6 * s, 0.61 * s, z + (this.r() - 0.5) * 0.4 * s, { noShadow: true });
    this.col(x, z, 0.6 * s, 0.6 * s);
  }
  acorns(x, z, n = 8) {
    for (let i = 0; i < n; i++) { const a = this.r() * 6, d = this.r() * 0.9, px = x + Math.cos(a) * d, pz = z + Math.sin(a) * d; const m = this.mesh(new THREE.SphereGeometry(0.18, 8, 6), 'wood', px, 0.2 + (i > 5 ? 0.25 : 0), pz); m.scale.y = 1.2; this.mesh(new THREE.SphereGeometry(0.19, 8, 4, 0, Math.PI * 2, 0, Math.PI / 2), 'bark', px, 0.33 + (i > 5 ? 0.25 : 0), pz); }
  }
  // 柱（遺跡・城）
  column(x, z, h = 6, r = 0.6, mat = 'marble') {
    this.box(x, z, r * 2.6, 0.5, r * 2.6, mat);
    this.cyl(x, z, r, h - 1, mat, { y: 0.5, seg: 14, r2: r * 0.9, col: false });
    this.box(x, z, r * 2.6, 0.5, r * 2.6, mat, { y: h - 0.5, col: false });
    this.col(x, z, r * 1.3, h);
  }
  pillarBroken(x, z, h, fallen = false, mat = 'stone') {
    if (fallen) { this.mesh(new THREE.CylinderGeometry(0.55, 0.6, h, 12), mat, x, 0.55, z, { rz: Math.PI / 2, ry: this.r() * 3 }); this.col(x, z, Math.min(h / 2, 2)); return; }
    this.cyl(x, z, 0.6, h, mat, { r2: 0.55, seg: 12 });
    this.box(x, z, 1.5, 0.4, 1.5, 'stone2', { col: false });
    if (this.r() < 0.6) { const m = this.mesh(new THREE.IcosahedronGeometry(0.5, 0), 'leaf', x + 0.3, h, z); m.scale.y = 0.4; }
  }
  // 壁画（ry = 絵の正面）
  mural(x, z, ry, kind = 0, w = 5, h = 3.2, y = 2.2) {
    const c = document.createElement('canvas'); c.width = 512; c.height = 320;
    const g = c.getContext('2d');
    g.fillStyle = '#c8b890'; g.fillRect(0, 0, 512, 320);
    for (let i = 0; i < 400; i++) { g.fillStyle = `rgba(${Math.random() < 0.5 ? '255,255,255' : '80,60,30'},${Math.random() * 0.12})`; g.fillRect(Math.random() * 512, Math.random() * 320, 4 + Math.random() * 20, 2 + Math.random() * 6); }
    g.strokeStyle = '#6a5030'; g.fillStyle = '#8a6a40'; g.lineWidth = 5; g.lineCap = 'round';
    const cat = (cx, cy, s, fill) => { g.beginPath(); g.ellipse(cx, cy, 28 * s, 34 * s, 0, 0, Math.PI * 2); fill ? g.fill() : g.stroke(); g.beginPath(); g.arc(cx, cy - 46 * s, 24 * s, 0, Math.PI * 2); fill ? g.fill() : g.stroke(); for (const sd of [-1, 1]) { g.beginPath(); g.moveTo(cx + sd * 12 * s, cy - 64 * s); g.lineTo(cx + sd * 22 * s, cy - 84 * s); g.lineTo(cx + sd * 26 * s, cy - 58 * s); g.stroke(); } };
    if (kind === 0) {   // 大きな樹を抱く巨大な猫
      g.lineWidth = 8; g.beginPath(); g.moveTo(256, 300); g.lineTo(256, 150); g.stroke();
      for (let i = 0; i < 7; i++) { g.beginPath(); g.arc(256 + Math.cos(i) * 70, 110 + Math.sin(i * 2) * 30, 50, 0, Math.PI * 2); g.stroke(); }
      g.lineWidth = 6; cat(256, 240, 2.2);
    } else if (kind === 1) {   // 樹のまわりで手をつなぐ四匹（一匹は小さい）
      g.lineWidth = 6; g.beginPath(); g.moveTo(256, 300); g.lineTo(256, 170); g.stroke(); g.beginPath(); g.arc(256, 130, 60, 0, Math.PI * 2); g.stroke();
      [[110, 250, 1], [190, 250, 1], [320, 250, 1], [400, 262, 0.7]].forEach(([cx, cy, s]) => cat(cx, cy, s));
      g.beginPath(); g.moveTo(138, 240); g.lineTo(162, 240); g.moveTo(348, 240); g.lineTo(380, 248); g.stroke();
    } else {   // 光る小さな猫と、枯れた樹
      g.lineWidth = 6; g.beginPath(); g.moveTo(256, 300); g.lineTo(256, 130); g.moveTo(256, 170); g.lineTo(200, 120); g.moveTo(256, 190); g.lineTo(320, 130); g.stroke();
      g.fillStyle = '#e8d890'; cat(256, 290, 0.7, true);
      g.strokeStyle = '#e8d890'; for (let i = 0; i < 10; i++) { const a = i / 10 * Math.PI * 2; g.beginPath(); g.moveTo(256 + Math.cos(a) * 50, 250 + Math.sin(a) * 50); g.lineTo(256 + Math.cos(a) * 75, 250 + Math.sin(a) * 75); g.stroke(); }
    }
    const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace;
    this.box(x, z, w + 0.5, h + 0.5, 0.3, 'stone2', { ry, y: y - h / 2 - 0.25 });
    this.mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshStandardMaterial({ map: t, roughness: 0.9 }), x + Math.sin(ry) * 0.17, y, z + Math.cos(ry) * 0.17, { ry, noShadow: true });
  }
  // 封印の扉
  sealDoor(x, z, ry = 0, open = false) {
    // 開いた扉は、柱とまぐさ石の枠だけ残して、くぐれるようにする
    if (open) { for (const sd of [-1, 1]) this.box(x + Math.cos(ry) * sd * 3.3, z - Math.sin(ry) * sd * 3.3, 1.4, 7, 1.2, 'stone2', { ry }); this.box(x, z, 8, 1.4, 1.2, 'stone2', { ry, y: 5.6 }); }
    else this.box(x, z, 8, 7, 1.2, 'stone2', { ry });
    const d = this.mesh(new THREE.CircleGeometry(2.6, 40), new THREE.MeshStandardMaterial({ color: '#8a846a', roughness: 0.8 }), x + Math.sin(ry) * 0.62, 3.2, z + Math.cos(ry) * 0.62, { ry, noShadow: true });
    const ring = this.mesh(new THREE.RingGeometry(2.3, 2.5, 48), this.glow('#8affe0', open ? 3 : 1.4), x + Math.sin(ry) * 0.65, 3.2, z + Math.cos(ry) * 0.65, { ry, noShadow: true });
    ring.material = ring.material.clone(); ring.material.side = THREE.DoubleSide;
    this.tick((dt, t) => { ring.rotation.z = t * 0.2; });
    return { d, ring };
  }
  // 猫じゃらし（魔王領の野原に生えている）
  nekojarashi(x, z, s = 1) {
    const stem = this.mesh(new THREE.CylinderGeometry(0.02 * s, 0.03 * s, 1.4 * s, 5), 'leaf2', x, 0.7 * s, z);
    const ear = this.mesh(new THREE.CapsuleGeometry(0.08 * s, 0.35 * s, 3, 8), '#e8d890', x, 1.55 * s, z);
    const ph = this.r() * 6, y0 = ear.position.y;
    this.tick((dt, t) => { const w = Math.sin(t * 1.6 + ph) * 0.2; stem.rotation.z = w * 0.5; ear.rotation.z = w; ear.position.x = x + w * 0.3 * s; });
  }
  spookyTree(x, z, s = 1) {
    this.cyl(x, z, 0.25 * s, 2.6 * s, 'darkStone', { r2: 0.12 * s, seg: 6 });
    for (let i = 0; i < 4; i++) this.mesh(new THREE.CylinderGeometry(0.03 * s, 0.08 * s, 1.3 * s, 5), 'darkStone', x, (1.6 + i * 0.25) * s, z, { rz: (i % 2 ? 1 : -1) * (0.7 + this.r() * 0.4), ry: i * 1.6 });
    const m = this.mesh(new THREE.IcosahedronGeometry(1.1 * s, 1), 'leafPurple', x, 3 * s, z); m.scale.y = 0.8;
    for (let i = 0; i < 3; i++) { const a = this.r() * 6; this.mesh(new THREE.SphereGeometry(0.1 * s, 8, 6), this.glow('#ff8ad8', 2), x + Math.cos(a) * 0.9 * s, 2.6 * s, z + Math.sin(a) * 0.9 * s, { noShadow: true }); }
  }
  // 巨大な根（アーチ）
  root(x0, z0, x1, z1, r = 1, h = 3) {
    const pts = [V3(x0, -0.5, z0), V3((x0 + x1) / 2, h, (z0 + z1) / 2), V3(x1, -0.5, z1)];
    const m = this.mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 16, r, 8, false), 'bark', 0, 0, 0, { abs: true });
    this.col(x0, z0, r * 1.2, 1); this.col(x1, z1, r * 1.2, 1);
    return m;
  }
  // 光る水晶の塊
  ore(x, z, n = 4, col = '#a07bff', s = 1) {
    const g = this.glow(col, 1.7);
    for (let i = 0; i < n; i++) { const h = (0.5 + this.r() * 0.9) * s, m = this.mesh(new THREE.OctahedronGeometry(0.28 * s, 0), g, x + (this.r() - 0.5) * s, h * 0.35, z + (this.r() - 0.5) * s, { rz: (this.r() - 0.5) * 0.8, ry: this.r() * 3, noShadow: true }); m.scale.y = h * 2.4; }
    this.col(x, z, 0.6 * s, 1.5 * s);
  }
  // 石筍
  stalag(x, z, h = 3) { const m = this.mesh(new THREE.ConeGeometry(0.5 + h * 0.12, h, 6), 'rockDark', x, h / 2, z, { ry: this.r() * 3 }); this.col(x, z, 0.4 + h * 0.1, h); return m; }
  floatRock(x, z, y, s = 1) {
    const m = this.mesh(new THREE.DodecahedronGeometry(s, 0), 'darkStone', x, y, z, { ry: this.r() * 3 }); m.scale.y = 0.6;
    const y0 = m.position.y, ph = this.r() * 6; this.tick((dt, t) => { m.position.y = y0 + Math.sin(t * 0.6 + ph) * 0.4; m.rotation.y += dt * 0.1; });
  }
  candy(x, z, s = 1) {
    const c = pick(['candyPink', 'candyBlue', 'candyYellow']);
    if (this.r() < 0.5) { this.cyl(x, z, 0.12 * s, 2.2 * s, 'cream', { seg: 8 }); this.mesh(new THREE.TorusGeometry(0.7 * s, 0.28 * s, 10, 20), c, x, 2.6 * s, z, { ry: this.r() * 3 }); }
    else { const m = this.mesh(new THREE.SphereGeometry(0.9 * s, 14, 10), c, x, 0.8 * s, z); for (let i = 0; i < 6; i++) this.mesh(new THREE.SphereGeometry(0.12 * s, 6, 4), pick(['candyPink', 'candyBlue', 'candyYellow', 'cream']), x + (this.r() - 0.5) * 1.4 * s, 0.9 * s + this.r() * 0.6 * s, z + (this.r() - 0.5) * 1.4 * s); this.col(x, z, 0.9 * s, 1.6 * s); }
  }
  // 外周の空いたところを土地に合った小物で埋める
  fill(style) {
    const Z = this.zone, hw = Z.w / 2, hd = Z.d / 2;
    const n = Math.round(Z.w * Z.d / 150);
    for (let i = 0, tries = 0; i < n && tries < n * 6; tries++) {
      const p = this.spot(2.5);
      if (Math.max(Math.abs(p.x) / hw, Math.abs(p.z) / hd) < 0.45) continue;
      if (this.v.safeAt && this.v.safeAt(p.x, p.z)) continue;
      i++;
      const r = this.r(), { x, z } = p;
      this.v.reserved.push({ x, z, r: 2 });
      switch (style) {
        case 'meadow': if (r < 0.4) this.roundTree(x, z, 0.8 + this.r() * 0.5, this.r() < 0.5 ? 'leaf' : 'leaf2', { fruit: this.r() < 0.2 ? '#ff8a8a' : null }); else if (r < 0.75) this.bush(x, z, 0.8 + this.r() * 0.4, 'leaf2', this.r() < 0.5 ? pick(['#ffffff', '#ffb8d8', '#ffe07a']) : null); else this.flowers(x, z, 12, 1.6); break;
        case 'forest': if (r < 0.5) this.roundTree(x, z, 0.9 + this.r() * 0.7, this.r() < 0.5 ? 'leaf' : 'leaf2', { lush: true }); else if (r < 0.7) this.mushroom(x, z, 0.8 + this.r() * 0.8, pick(['#e05a6a', '#ffb84a']), this.r() < 0.3 ? pick(['#8affc8', '#b8a8ff']) : null); else if (r < 0.85) this.bush(x, z, 1); else this.log(x, z, 2 + this.r() * 2, this.r() * 3); break;
        case 'road': if (r < 0.4) this.roundTree(x, z, 0.9 + this.r() * 0.4); else if (r < 0.7) this.flowers(x, z, 14, 2, ['#ffe07a', '#ffffff', '#ffb84a']); else if (r < 0.85) this.rock(x, z, 0.6 + this.r() * 0.6); else this.bush(x, z, 1); break;
        case 'valley': if (r < 0.45) this.deadTree(x, z, 0.9 + this.r() * 0.5); else if (r < 0.8) this.rock(x, z, 0.8 + this.r() * 0.8, this.r() < 0.5 ? 'rock' : 'rockDark'); else this.flowers(x, z, 6, 1.2, ['#c8a8ff', '#ffffff']); break;
        case 'ruins': if (r < 0.5) this.pillarBroken(x, z, 1.5 + this.r() * 4, this.r() < 0.35); else if (r < 0.75) this.roundTree(x, z, 0.8 + this.r() * 0.5, 'leaf2'); else this.rock(x, z, 0.8, 'stone2'); break;
        case 'demon': if (r < 0.4) this.spookyTree(x, z, 0.9 + this.r() * 0.4); else if (r < 0.75) for (let k = 0; k < 4; k++) this.nekojarashi(x + (this.r() - 0.5) * 2, z + (this.r() - 0.5) * 2, 0.8 + this.r() * 0.5); else this.rock(x, z, 0.8, 'purpleStone'); break;
        case 'tree': if (r < 0.5) this.roundTree(x, z, 0.8 + this.r() * 0.5, 'leafGray'); else if (r < 0.8) this.rock(x, z, 0.8); else this.flowers(x, z, 6, 1.2, ['#c8c8b8']); break;
        case 'end': if (r < 0.6) this.rock(x, z, 1 + this.r() * 1.2, 'darkStone'); else this.floatRock(x, z, 3 + this.r() * 4, 0.6 + this.r() * 0.8); break;
        case 'dream': this.candy(x, z, 0.8 + this.r() * 0.6); break;
      }
    }
  }
}

// 土の道（x0,z0 → x1,z1）
ZoneKit.prototype.path = function (x0, z0, x1, z1, w = 3, col = '#b8946a') {
  const len = Math.hypot(x1 - x0, z1 - z0), key = 'path' + col;
  const m = this.mc[key] || (this.mc[key] = new THREE.MeshStandardMaterial({ color: col, roughness: 1, transparent: true, opacity: 0.9, depthWrite: false }));
  const p = this.mesh(new THREE.PlaneGeometry(w, len + w * 0.6), m, (x0 + x1) / 2, 0.02, (z0 + z1) / 2, { rx: -Math.PI / 2, noShadow: true });
  p.rotation.z = -Math.atan2(x1 - x0, -(z1 - z0)); p.renderOrder = -1; p.receiveShadow = true;
  const disc = this.mesh(new THREE.CircleGeometry(w / 2, 16), m, x1, 0.021, z1, { rx: -Math.PI / 2, noShadow: true }); disc.receiveShadow = true;
};
// 川（colliders で渡れない。bridges の位置だけ通れる）
ZoneKit.prototype.river = function (z, w, x0, x1, bridges = []) {
  this.water((x0 + x1) / 2, z, x1 - x0, w);
  let x = x0;
  for (const b of [...bridges].sort((a, c) => a - c)) { if (b - 1.6 > x) this.colBox((x + b - 1.6) / 2, z, (b - 1.6 - x) / 2, w / 2, 0.2); x = b + 1.6; }
  if (x < x1) this.colBox((x + x1) / 2, z, (x1 - x) / 2, w / 2, 0.2);
  bridges.forEach(b => this.bridge(b, z, w + 2.4, 0));
};

// ============================================================
//  区画ごとの組み立て
// ============================================================
const ZONE_BUILD = {
  // ---------------- 第一章 ----------------
  // ぽかぽか村：広場の井戸、村長の家、ミケの家、商店、魚屋、猫神社
  village(K) {
    K.perimeter('fence');
    const post = storyCond('done');
    K.mesh(new THREE.CircleGeometry(10, 40), new THREE.MeshStandardMaterial({ color: '#c8b494', roughness: 1 }), 0, 0.015, 2, { rx: -Math.PI / 2, noShadow: true }).receiveShadow = true;
    K.path(0, 2, -10, -31, 3.2); K.path(0, 2, 35, 10, 3.2); K.path(0, 2, 8, 31, 3.2); K.path(4, -2, 24, -8, 2.6); K.path(24, -8, 35, -22, 2);
    K.well(0, 2);
    K.catHouse(0, -20, 9, 7, 4, 's', { roof: 'roofRed', sign: '村長の家', lit: true, smoke: true });
    K.catHouse(-26, -8, 6, 6, 3.4, 'e', { roof: 'roofOrange', sign: post ? 'ミケの家（魚屋）' : 'ミケの家' });
    K.fishRack(-24, -2.5, Math.PI / 2);
    K.catHouse(-18, 18, 7, 5, 3.6, 'n', { roof: 'roofBlue', sign: '武器屋', sub: 'つめとぎ・つるぎ' });
    K.catHouse(-5, 19, 6, 5, 3.4, 'n', { roof: 'roofGreen', sign: '道具屋' });
    K.catHouse(11, 20, 8, 6, 4.2, 'n', { roof: 'roofRed', sign: '宿屋 ひだまり亭', lit: true });
    K.catHouse(-24, -22, 6, 5, 3.4, 's', { roof: 'roofGreen' });
    K.catHouse(-30, 12, 5, 5, 3.2, 'e', { roof: 'roofBlue' });
    K.catHouse(14, -22, 6, 5, 3.4, 's', { roof: 'roofOrange' });
    // 魚屋の屋台と干し魚
    K.stall(18.5, 1.5, -Math.PI / 2, 'clothRed', ['#8ab8d8', '#b8c8d8', '#ff9a7a']);
    K.sign(17.2, 1.5, -Math.PI / 2, post ? 'ミケと魚屋' : '魚屋', '今日のおすすめ：焼き魚', '#8ad8ff', 3.1, 2.6);
    K.fishRack(21, -5, 0); K.fishRack(21, 8, 0); K.barrel(16.5, -2); K.barrel(16, 5);
    // 猫神社
    K.torii(24, -9, 0, 1); K.shrine(24, -23, 0);
    K.stoneLantern(21, -13); K.stoneLantern(27, -13);
    for (let z = -12; z > -20; z -= 1.6) K.mesh(new THREE.BoxGeometry(1.6, 0.06, 1), 'stone', 24, 0.03, z, { noShadow: true });
    // 村の小物
    for (const [x, z, ry] of [[-6, 8, 0.4], [6, -4, -0.6]]) K.bench(x, z, ry);
    for (const [x, z] of [[-10, -6], [9, 10], [-14, 8], [4, -12]]) K.lantern(x, z, '#ffc86a', 2.6);
    for (const [x, z] of [[-8, 12], [8, 12], [-12, -12], [12, -10], [-30, -2], [30, 18]]) K.flowers(x, z, 14, 1.8);
    for (const [x, z, s] of [[-32, -26, 1.3], [-6, -28, 1.1], [30, 26, 1.2], [-32, 26, 1.4], [32, -30, 1.1], [-14, 28, 1], [22, 28, 1]]) K.roundTree(x, z, s, 'leaf', { fruit: s > 1.2 ? '#ff8a8a' : null });
    K.crate(-14, 21); K.crate(-13, 22.2, 0.8); K.barrel(-22, 21);
    K.light(0, 5, 2, '#fff0c8', 6, 24);
  },
  // 村はずれの丘：丘の上に流れ星の落ちたクレーター、西の見晴らしに大きな木とベンチ
  hill(K) {
    K.flora({ trees: [['round', 4], ['pine', 1]], leaf: ['#6abf52', '#5ab04a', '#7ac85a'], fruit: '#ff9a9a', bush: 0.7, flower: ['#ffffff', '#ffe07a', '#ffb8d8'] });
    K.crater(0, -4, 5);
    if (storyCond('scene:c1_02') && !storyCond('scene:c1_03')) K.starRock(0, -4, 1.1); else if (storyCond('scene:c1_03')) K.starRock(-3, -5, 0.4);
    K.roundTree(-14, 8, 1.7, 'leaf', { lush: true, fruit: '#ff9a9a' }); K.bench(-11, 10, 0.5);
    K.flowers(-8, 14, 16, 2.5); K.flowers(12, 6, 12, 2, ['#ffe07a', '#ffffff']); K.flowers(-16, -16, 16, 3); K.flowers(14, -16, 12, 2.5, ['#ffe07a', '#ffffff']);
    for (const [x, z, sz] of [[16, -18, 1.2], [-20, -14, 0.9], [22, 3, 0.8]]) K.rock(x, z, sz);
    K.signpost(-5, 18, 0, '↓ にゃんだーの樹', '↑ ぽかぽか村');
  },
  // ほしふる森・入口：小川と二本の橋、光るきのこの輪、北の広場の倒木
  forest(K) {
    K.flora({ trees: [['round', 4], ['pine', 1.2], ['mush', 0.3]], leaf: ['#5ab04a', '#4a9a3e', '#62b44e', '#3f8a3a'], bush: 0.8, flower: ['#fff4a8', '#ffffff', '#ffb8d8'] });
    // 目印の大きな木（星の実がなる）
    K.bigTree(-18, -4, 1.2, 'leaf2', '#fff4a8'); K.bigTree(19, 4, 1.1, 'leaf', '#b8ffd8');
    // 西の小さな広場：光るきのこの輪
    for (let i = 0; i < 8; i++) { const a = i / 8 * Math.PI * 2; K.mushroom(-21 + Math.cos(a) * 2, 10 + Math.sin(a) * 2, 0.7, null, '#8affc8'); }
    K.v.emitters.push(dt => { if (Math.random() < dt * 5) K.v.p.emit(V3(-21 + (Math.random() - 0.5) * 3, K.gy(-21, 10) + 0.4, 10 + (Math.random() - 0.5) * 3), V3(0, 0.6, 0), hdr('#8affc8', 2), { life: 2.2, size: 0.07, drag: 0 }); });
    // 北の広場：倒木と花畑、北西の茂みの赤いきのこ
    K.log(12, -12, 3, 0.6); K.flowers(10, -20, 14, 2, ['#fff4a8', '#ffffff']); K.flowers(-16, -16, 10, 1.6);
    for (const [x, z] of [[-26, -28], [-22, -26], [-20, -30]]) K.mushroom(x, z, 0.9, '#e05a6a');
    // 立て札の広場と、橋のたもと
    K.flowers(16, 12, 12, 2, ['#ffe07a', '#ffffff']); K.stoneLantern(-3.2, 3); K.stoneLantern(3.2, 3);
    // 南東の高台：切り株と花
    K.cyl(20, 20, 0.7, 0.5, 'bark', { seg: 10 }); K.flowers(22, 28, 12, 2, ['#ffb8d8', '#ffffff']);
  },
  // ほしふる森・奥：巨木、星の泉、光るきのこの輪（南西の広場）
  forestDeep(K) {
    K.flora({ trees: [['round', 3], ['pine', 2], ['mush', 0.5]], leaf: ['#3f8a3a', '#4a9a3e', '#35803a', '#56a444'], caps: ['#b88aff', '#e05a6a', '#8ad8ff'], bush: 0.85, flower: ['#fff4a8', '#b8ffd8'] });
    K.bigTree(6, -24, 1.2, 'leaf2', '#fff4a8'); K.bigTree(-24, 2, 1.1, 'leaf', '#b8ffd8'); K.bigTree(26, 10, 1.0, 'leaf2', '#fff4a8');
    for (let i = 0; i < 9; i++) { const a = i / 9 * Math.PI * 2; K.mushroom(-20 + Math.cos(a) * 2.6, 14 + Math.sin(a) * 2.6, 0.7, null, '#8affc8'); }
    K.v.emitters.push(dt => { if (Math.random() < dt * 6) K.v.p.emit(V3(-20 + (Math.random() - 0.5) * 4, 0.4, 14 + (Math.random() - 0.5) * 4), V3(0, 0.6, 0), hdr('#8affc8', 2), { life: 2.4, size: 0.08, drag: 0 }); });
    // 星の泉：水面から光の粒が立ちのぼる
    K.v.emitters.push(dt => { if (Math.random() < dt * 8) K.v.p.emit(V3(19 + (Math.random() - 0.5) * 7, -0.3, 0 + (Math.random() - 0.5) * 4), V3(0, 0.8, 0), hdr('#fff4a8', 2.2), { life: 2.6, size: 0.07, drag: 0 }); });
    for (const [x, z] of [[14, -1], [24, -6], [26, 2]]) K.rock(x, z, 0.5 + K.r() * 0.3);
    // 巨木の根の高台：古い切り株
    K.cyl(-24, -18, 1.1, 0.7, 'bark', { seg: 12 }); K.flowers(-22, -14, 10, 1.6, ['#fff4a8', '#ffffff']);
    K.log(6, -12, 3, 0.3);
  },
  // ネズミの王国：巨大な根のアーチの下の大広間、どんぐりの玉座、ネズミの家、チーズの倉
  ratNest(K) {
    K.flora({ trees: [['round', 2], ['mush', 1]], leaf: ['#3f8a3a', '#4a9a3e'], caps: ['#ffb84a', '#e05a6a'], bush: 0.9 });
    K.root(-14, -24, 14, -24, 1.6, 9); K.root(-20, -16, -6, -26, 1.1, 6); K.root(20, -16, 6, -26, 1.1, 6); K.root(-6, 6, 8, 4, 1.0, 7);
    K.box(0, -20, 3, 1.4, 2, 'wood2', { round: true }); K.acorns(0, -20.5, 12);
    K.mesh(new THREE.CylinderGeometry(1.2, 1.4, 2.4, 12, 1, true, Math.PI * 0.2, Math.PI * 0.6), 'wood', 0, 1.6, -20.8, { ry: Math.PI });
    for (const [x, z, sz] of [[-10, -16, 1], [10, -16, 1], [-12, -2, 0.9], [12, -2, 0.9], [20, -14, 0.8], [22, -10, 0.8]]) K.ratHouse(x, z, sz, Math.atan2(-x, -z));
    for (const [x, z] of [[-20, -8], [-22, -6], [-24, -14], [-8, -12]]) K.cheese(x, z, 0.8 + K.r() * 0.5);
    for (const [x, z] of [[-6, -18], [6, -18], [-15, -14], [16, -12]]) K.mushroom(x, z, 1.2, null, '#ffd27a');
    K.acorns(-16, -2, 8); K.acorns(22, -16, 8); K.acorns(-10, 8, 6);
  },

  // ---------------- 第二章 ----------------
  // ミャオ街道・丘：うねる道、東の風車と畑、西のひょうたん池、北の見晴らし台
  road(K) {
    K.flora({ trees: [['round', 4], ['pine', 1]], leaf: ['#6abf52', '#7ac85a', '#5ab04a'], fruit: '#ff9a7a', bush: 0.6, rocks: 0.5, flower: ['#ffe07a', '#ffffff', '#ffb84a'] });
    K.windmill(18, -13.5, 1);
    for (let i = 0; i < 3; i++) K.mesh(new THREE.BoxGeometry(8, 0.35, 0.8), 'leaf2', 17, 0.18, -8 + i * 2, { noShadow: true });
    for (let i = 0; i < 3; i++) K.mesh(new THREE.BoxGeometry(8, 0.5, 0.8), '#e8c060', 17, 0.25, -1 + i * 2, { noShadow: true });
    // 休み場の広場：荷車と樽
    K.barrel(-17, 0); K.barrel(-16, 1.4); K.crate(-18, 4); K.lantern(-15, 8, '#ffc86a');
    // ひょうたん池と、見晴らし台・東の休み場のベンチ
    for (let i = 0; i < 5; i++) K.mesh(new THREE.CircleGeometry(0.35, 10), 'leaf2', -20 + K.r() * 3, 0.03, 23 + K.r() * 4, { rx: -Math.PI / 2, noShadow: true });
    K.flowers(-18, 28, 12, 2); K.bench(-16, -41, 0.3); K.bench(8, -35, -0.4); K.flowers(10, -34, 10, 1.5, ['#ffe07a', '#ffffff']);
    K.flowers(0, 38, 14, 3); K.flowers(10, 42, 10, 2, ['#ffb8d8', '#ffffff']);
  },
  // 街道の宿場：茶屋・屋台・井戸
  rest(K) {
    K.perimeter('fence');
    K.path(4, 27, 0, 2, 3); K.path(0, 2, -4, -27, 3); K.path(0, 2, 29, 6, 2.6);
    K.catHouse(-10, -8, 7, 6, 3.6, 's', { roof: 'roofGreen', sign: '茶屋 ねこじゃらし', lit: true, smoke: true });
    K.catHouse(12, -16, 7, 5, 3.4, 's', { roof: 'roofRed', sign: '旅人の宿', lit: true });
    K.catHouse(-20, 12, 5, 5, 3.2, 'e', { roof: 'roofBlue' });
    K.stall(19, 4, -Math.PI / 2, 'clothYellow', ['#c8c8d8', '#8a8a96', '#ffd27a']); K.sign(18, 4, -Math.PI / 2, '旅の鍛冶屋', null, '#ffd27a', 3.1, 2.4);
    K.stall(8, 12, Math.PI, 'clothPink');
    K.well(0, -2);
    for (const [x, z] of [[-6, 4], [6, -6]]) K.bench(x, z, 0.3);
    for (const [x, z] of [[-4, -4], [5, 3]]) K.lantern(x, z, '#ffc86a');
    // シロの魔法の失敗で降ってきた魚
    if (storyCond('scene:c2_02')) for (let i = 0; i < 6; i++) { const f = K.mesh(new THREE.SphereGeometry(0.14, 8, 6), '#8ab8d8', 2 + K.r() * 3, 0.1, 3 + K.r() * 3, { ry: K.r() * 3 }); f.scale.set(0.5, 0.5, 2); }
    K.fill('road');
  },
  // まどろみの林：タマが眠っていた大きな木のうろ、舞う綿毛、花の丘、南東の池
  woods(K) {
    K.flora({ trees: [['round', 3], ['pine', 1]], leaf: ['#7ac85a', '#8ad06a', '#6abf52'], bush: 0.8, flower: ['#ffffff', '#fff8c8'] });
    K.bigTree(4, -26, 1.3, 'leaf', '#fff0a8');
    const hol = K.mesh(new THREE.CircleGeometry(1.2, 20), 'wood2', 4, 1.2, -24.2, { noShadow: true }); hol.scale.y = 1.2;
    for (let i = 0; i < 20; i++) K.mesh(new THREE.SphereGeometry(0.12, 6, 4), pick(['#e8a040', '#d8783a', '#f0c060']), 4 + (K.r() - 0.5) * 3, 0.05, -21.5 + (K.r() - 0.5) * 2, { noShadow: true }).scale.y = 0.3;
    K.flowers(-2, -22, 12, 2, ['#ffffff', '#fff8c8']); K.flowers(22, -2, 18, 2.5, ['#ffb8d8', '#ffffff', '#fff8c8']); K.flowers(-20, 10, 10, 2, ['#ffffff']);
    for (let i = 0; i < 6; i++) K.mesh(new THREE.CircleGeometry(0.4, 10), 'leaf2', 6 + K.r() * 6, 0.03, 16 + K.r() * 4, { rx: -Math.PI / 2, noShadow: true });
    K.log(-10, -8, 2.6, 1.2);
    K.v.emitters.push(dt => { if (Math.random() < dt * 8) K.v.p.emit(V3((Math.random() - 0.5) * 40, 0.5 + Math.random(), (Math.random() - 0.5) * 50), V3(0.3, 0.2, 0), hdr('#ffffff', 1.2), { life: 5, size: 0.06, drag: 0 }); });
  },
  // 街道の関所あと：岩山の切り通し、こわれた門、東の野営あと
  checkpoint(K) {
    K.cragTop({ trees: [['dead', 1], ['round', 1]], leaf: ['#8aa860', '#7a9a58'], density: 0.25 });
    for (const x of [-3.5, 3.5]) K.box(x, -18, 0.6, 4.4, 0.6, 'wood2');
    K.mesh(new THREE.BoxGeometry(8.5, 0.5, 0.6), 'wood2', 1.5, 0.4, -16.6, { rz: 0.25, ry: 0.2 });
    K.box(12, -14, 4, 1, 0.3, 'wood', { ry: -0.3 });
    // 倒れた関所の札（地面に倒れている。調べられる）
    K.box(-10, -12, 3.4, 0.14, 0.9, 'wood', { ry: 0.3, col: false });
    K.mesh(new THREE.PlaneGeometry(3.2, 0.8), new THREE.MeshBasicMaterial({ map: signTex('ニャハハ王国まで あと少し', '笑顔でお越しください'), transparent: true, toneMapped: false }), -10, 0.15, -12, { rx: -Math.PI / 2, rz: 0.3, noShadow: true });
    K.sign(0, -18.4, 0, '関所', 'ニャハハ王国', '#ffd27a', 4.8, 2.8);
    // 野営あと
    K.mesh(new THREE.CircleGeometry(4, 24), new THREE.MeshStandardMaterial({ color: '#9a7a52', roughness: 1 }), 20, 0.02, 5, { rx: -Math.PI / 2, noShadow: true });
    K.tent(20, 6.5, -0.4, 'clothYellow'); K.campfire(17, 2.5);
    for (const [x, z] of [[15.5, 3], [24, 7]]) K.barrel(x, z);
    K.crate(-10, 6); K.crate(-9, 7.3, 0.8);
    for (const [x, z] of [[-6, 28], [6, 30], [-8, -2], [8, -4]]) K.rock(x, z, 0.6 + K.r() * 0.4);
  },

  // ---------------- 第三章 ----------------
  // ニャハハ王国：色を失った街（第三章を終えると色が戻る）。家並みは地図の敷地から建てる
  kingdom(K) {
    const happy = kingdomJoy();
    const flagCols = happy ? ['#ff6a8a', '#ffd27a', '#6ad8ff', '#8aff9a', '#b88aff'] : ['#8a8a90', '#a0a0a8', '#b4b4ba'];
    const bannerCols = happy ? ['#e87aa8', '#5a8ad8', '#e87aa8', '#5a8ad8'] : ['#8a8a96', '#9a9aa4'];
    K.townBlocks({ happy });
    // 地図の外：家並み、北に城、北東に笑顔の塔
    K.castleKeep(-12, -72, { happy, s: 1.1 }); K.smileTower(30, -62, { happy });
    K.townBackdrop({ happy, skip: (x, z) => (z < -40 && x > -40 && x < 18) || Math.hypot(x - 30, z + 62) < 12 });

    // ---- 大広場：二段の噴水と笑う猫の像、ベンチ、植え込み、街灯 ----
    K.cyl(0, -8, 4.2, 0.55, 'stone', { seg: 32 });
    K.mesh(new THREE.CylinderGeometry(3.9, 3.9, 0.06, 32), new THREE.MeshStandardMaterial({ color: happy ? '#7ad0f8' : '#8a9aa8', transparent: true, opacity: 0.8, roughness: 0.05, emissive: happy ? '#3a90d0' : '#2a3a48', emissiveIntensity: 0.3 }), 0, 0.46, -8, { noShadow: true });
    K.fountain(0, -8, !happy);
    K.catStatue(-8, -8, 0.4, 1.1, happy ? 'marble' : 'stone');
    for (const a of [0.8, 2.35, 3.9, 5.5]) K.bench(Math.sin(a) * 6.6, -8 + Math.cos(a) * 6.6, a);
    for (const [x, z] of [[-14, -12], [14, -12], [-14, 2], [14, 2]]) K.planterTree(x, z, 1.1, happy);
    for (const [x, z] of [[-13.8, -13.4], [13.8, -13.4], [-20, -13.5], [20, -13.5], [-20, 7.5], [20, 7.5], [-8, 7.5], [8, 7.5]]) K.streetLamp(x, z, happy);
    K.flowers(-18, -4, 14, 2, happy ? ['#ff8ab8', '#ffd24a', '#ffffff'] : ['#a8a8a0']); K.flowers(18, -6, 14, 2, happy ? ['#ffb8d8', '#ffffff', '#b8d8ff'] : ['#a8a8a0']);
    K.bunting(-22, -13, 22, -13, flagCols, 5.2); K.bunting(-22, 7, 22, 7, flagCols, 5.2);
    // 大階段の両脇の猫の像と、高台の擁壁から下がる垂れ幕
    K.catStatue(-11.5, -13.6, 0, 1.4, happy ? 'marble' : 'stone', happy ? '#ffd27a' : null);
    K.catStatue(11.5, -13.6, 0, 1.4, happy ? 'marble' : 'stone', happy ? '#ffd27a' : null);
    [-21, -16, 16, 21].forEach((x, i) => K.banner(x, -14.95, 0, 2.9, 2.2, bannerCols[i % bannerCols.length]));
    // 店の看板（広場の西と東の家並み）
    const signCol = happy ? '#ffd27a' : '#c8c8d0';
    for (const [x, z, ry, t, sub] of [[-23.9, -10, Math.PI / 2, 'パン屋 こむぎ', '焼きたて'], [-23.9, 2, Math.PI / 2, '花屋', 'ねこじゃらしあります'],
      [23.9, -11, -Math.PI / 2, '雑貨屋', 'なんでもあるにゃ'], [23.9, -1, -Math.PI / 2, 'ミルク屋', happy ? '本日も新鮮' : '休業中'], [9.9, 16, -Math.PI / 2, 'カフェ にゃんぷー', null], [9.9, 31, -Math.PI / 2, 'おみやげ', null]])
      K.sign(x, z, ry, t, sub, signCol, 3.2, 2.4);

    // ---- 南の大通り：「ようこそ」のアーチ、並木、街灯、旗飾り ----
    for (const x of [-7.5, 7.5]) { K.box(x, 31.5, 1.2, 6.2, 1.2, 'stone', { round: true }); K.mesh(new THREE.ConeGeometry(0.9, 1.2, 4), happy ? 'roofRed' : 'roofGray', x, 6.8, 31.5, { ry: Math.PI / 4 }); }
    K.mesh(new THREE.BoxGeometry(16, 0.7, 1.0), 'stone', 0, 5.6, 31.5);
    K.sign(0, 32.05, 0, 'ようこそ ニャハハ王国へ', 'わらいの都', signCol, 5.0, 6.4);
    K.sign(0, 30.95, Math.PI, 'ニャハハ王国', 'またきてね', signCol, 5.0, 5.0);
    for (const [x, z] of [[-8.5, 18], [8.5, 20], [-8.5, 26], [8.5, 26]]) K.planterTree(x, z, 1, happy);
    for (const [x, z] of [[-8.8, 13], [-8.8, 22], [8.8, 23], [-8.8, 29], [8.8, 29]]) K.streetLamp(x, z, happy);
    for (const z of [16, 24]) K.bunting(-9.6, z, 9.6, z + 1, flagCols, 5.4);

    // ---- 北の高台：城への坂と塔への小道、花壇と街灯 ----
    K.signpost(-12, -21, 0, '↑ ニャハハ城', '王さまのお城', signCol);
    K.signpost(20, -21, 0, '↑ 笑顔の塔', 'この先', signCol);
    for (const x of [-28, -20, -2, 6, 26]) K.planterTree(x, -21, 0.9, happy);
    for (const x of [-24, -6, 2, 10, 30]) K.streetLamp(x, -19.5, happy);
    for (const x of [-15, -5]) K.streetLamp(x, -30, happy);
    K.bunting(-15, -27, -5, -27, flagCols, 4.6);
    K.flowers(-10, -24, 16, 2.5, happy ? ['#ff8ab8', '#ffd24a', '#ffffff'] : ['#a8a8a0']); K.flowers(20, -28, 10, 1.6, happy ? ['#ffb8d8', '#ffffff'] : ['#a8a8a0']);

    // ---- 西の宿屋の街区（一段高い） ----
    K.sign(-23.9, 14, Math.PI / 2, '宿 わらいねこ亭', happy ? 'ようこそ！' : null, signCol, 3.3, 2.6);
    for (const [x, z] of [[-18, 24], [-18, 31]]) K.streetLamp(x, z, happy);
    K.planterTree(-12.5, 20, 0.8, happy); K.barrel(-23, 22); K.barrel(-22.2, 23.2); K.crate(-23, 30);
    K.flowers(-14, 32, 10, 1.4, happy ? ['#ff8ab8', '#ffd24a'] : ['#a8a8a0']);

    // ---- 東の市場通り：運河ぞいの屋台、小舟、橋の灯り ----
    K.stall(25.5, 14, -Math.PI / 2, happy ? 'clothYellow' : 'stone2', ['#ffd27a', '#8ad8ff', '#ff9a7a']);
    K.sign(24.4, 14, -Math.PI / 2, '道具屋', null, signCol, 3.0, 2.2);
    K.stall(25.5, 22, -Math.PI / 2, happy ? 'clothRed' : 'stone2', ['#8ab8d8', '#b8c8d8', '#ff9a7a']);
    K.stall(25.5, 29, -Math.PI / 2, happy ? 'clothPink' : 'stone2', ['#ffd24a', '#ff8ab8', '#8aff9a']);
    K.stall(16, 12, Math.PI / 2, happy ? 'clothPurple' : 'stone2', ['#ff8ab8', '#ffffff', '#b88aff']);
    K.stall(16, 31, Math.PI / 2, happy ? 'cloth' : 'stone2', ['#ffd27a', '#e8c060', '#ff9a7a']);
    for (const [x, z] of [[18, 17], [22.5, 25.5], [17, 27]]) K.barrel(x, z);
    for (const [x, z] of [[23, 18], [16.5, 16]]) K.crate(x, z);
    for (const z of [11, 26, 32]) K.streetLamp(29.2, z, happy);
    K.boat(32, 14, 0.1, happy ? '#c86a4a' : '#6a6260'); K.boat(32.2, 29, -0.15, happy ? '#4a8ac8' : '#6a6260');
    for (const [x, z] of [[29.4, 3.4], [29.4, 8.6], [34.6, 3.4], [34.6, 8.6]]) K.streetLamp(x, z, happy, 3.2);
    K.bunting(29.4, 3.4, 34.6, 3.4, flagCols, 3.6, false); K.bunting(29.4, 8.6, 34.6, 8.6, flagCols, 3.6, false);
    K.bunting(24.5, 20.5, 29, 20.5, flagCols, 5);

    if (happy) K.light(0, 7, -8, '#fff0c8', 8, 34);
  },
  // ニャハハ城・中庭：回廊に囲まれた中庭、北の前庭と城内への扉、生け垣と噴水、城壁の垂れ幕と塔
  castle(K) {
    const happy = kingdomJoy();
    const clothC = happy ? '#e87aa8' : '#9a8a98';
    // 赤いじゅうたん：門から石段まで、前庭は城内への扉まで
    K.mesh(new THREE.PlaneGeometry(3.6, 29.5), 'clothRed', 0, 0.03, 6.25, { rx: -Math.PI / 2, noShadow: true });
    K.mesh(new THREE.PlaneGeometry(3.6, 7.6), 'clothRed', 0, 0.03, -16.8, { rx: -Math.PI / 2, noShadow: true });
    for (const x of [-1.9, 1.9]) K.mesh(new THREE.BoxGeometry(0.12, 0.04, 29.5), 'gold', x, 0.04, 6.25, { noShadow: true });
    // 城内への扉の両脇：柱と金の猫の像、花の鉢
    for (const x of [-3.6, 3.6]) { K.column(x, -20, 7, 0.5, 'marble'); K.mesh(new THREE.SphereGeometry(0.3, 12, 10), 'gold', x, 7.3, -20); }
    K.catStatue(-11, -18, 0.4, 1.3, 'marble', happy ? '#ffd27a' : null); K.catStatue(11, -18, -0.4, 1.3, 'marble', happy ? '#ffd27a' : null);
    for (const x of [-7, 7]) { K.cyl(x, -19.4, 0.55, 0.8, 'marble', { seg: 12 }); K.mesh(new THREE.SphereGeometry(0.62, 14, 10), happy ? 'leaf' : 'leafGray', x, 1.25, -19.4); if (happy) K.flowers(x, -19.4, 6, 0.5, ['#ff8ab8', '#ffd24a']); }
    // 回廊：左右の列柱と屋根（金の縁）
    for (const sd of [-1, 1]) {
      for (let z = -5; z <= 19; z += 6) K.column(sd * 12.6, z, 5.2, 0.42, 'marble');
      K.mesh(new THREE.BoxGeometry(4.2, 0.4, 27.4), 'marble', sd * 14.2, 5.35, 7);
      K.mesh(new THREE.BoxGeometry(0.2, 0.3, 27.4), 'gold', sd * 12.15, 5.3, 7);
      const rf = new THREE.BoxGeometry(4.8, 0.2, 27.8); K.mesh(rf, happy ? 'roofRed' : 'roofGray', sd * 14.1, 5.8, 7, { rz: sd * 0.25 });
    }
    // 生け垣の庭と猫のトピアリー、小さな噴水
    for (const sd of [-1, 1]) {
      K.box(sd * 8.5, -1, 3.2, 0.9, 1.2, 'leaf2', { round: true });
      const tx = sd * 8.5, tz = -3.4;
      K.cyl(tx, tz, 0.7, 0.5, 'stone', { seg: 10 });
      K.mesh(new THREE.SphereGeometry(0.75, 14, 10), happy ? 'leaf' : 'leafGray', tx, 1.2, tz);
      K.mesh(new THREE.SphereGeometry(0.55, 14, 10), happy ? 'leaf' : 'leafGray', tx, 2.2, tz);
      for (const e of [-1, 1]) { const ear = new THREE.ConeGeometry(0.18, 0.4, 4); K.mesh(ear, happy ? 'leaf' : 'leafGray', tx + e * 0.3, 2.75, tz, { rz: -e * 0.3 }); }
      K.fountain(sd * 8.5, 17, !happy);
      K.flowers(sd * 8.5, 1.5, 10, 1.4, happy ? ['#ff8ab8', '#ffd24a', '#ffffff'] : ['#a8a8a0']);
    }
    // 城壁の垂れ幕（回廊の屋根の上）と、北の壁の紋章の旗
    for (const sd of [-1, 1]) for (const z of [-3, 3, 9, 15]) K.banner(sd * 15.95, z, sd > 0 ? -Math.PI / 2 : Math.PI / 2, 9.4, 3, clothC);
    for (const x of [-7, 7]) K.banner(x, -20.95, 0, 11.4, 3.6, clothC, '#ffd27a', 1.6);
    // 城壁の角の塔と、門の両脇の塔（とんがり屋根）
    const roofs = happy ? ['roofRed', 'roofBlue', 'roofPurple'] : ['roofGray'];
    for (const [x, z, h, r0] of [[-18, -21, 17, 2.6], [18, -21, 17, 2.6], [-18, 21, 15, 2.4], [18, 21, 15, 2.4], [-4.5, 22.5, 13.5, 1.8], [4.5, 22.5, 13.5, 1.8]]) {
      K.mesh(new THREE.CylinderGeometry(r0, r0 * 1.06, h, 16), 'marble', x, h / 2 - 1, z);
      K.mesh(new THREE.ConeGeometry(r0 * 1.3, r0 * 2.4, 16), roofs[Math.abs(Math.round(x + z)) % roofs.length], x, h - 1 + r0 * 1.2, z);
      K.mesh(new THREE.BoxGeometry(0.6, 1.1, r0 * 2 + 0.05), happy ? K.glow('#ffd8a0', 1.2) : '#6a6a78', x, h - 3.2, z);
    }
    K.castleKeep(0, -40, { happy, s: 0.9 });
    // 灯り
    for (const [x, z] of [[-4, 19], [4, 19], [-4, -7], [4, -7], [-5, -14], [5, -14]]) K.brazier(x, z, happy ? '#ffb04a' : '#c8b8a0', 1.2);
    K.light(0, 6, -14, '#fff0d8', 7, 22);
  },
  // ニャハハ城の中：玉座の間（列柱・壇・天蓋つきの玉座・シャンデリア）、宝物庫、図書室、大広間（肖像画）、食堂、厨房
  castleIn(K) {
    const happy = kingdomJoy(), T = K.T;
    const clothC = happy ? '#e87aa8' : '#9a8a98', lit = happy ? '#ffd8a0' : '#e8e0d0';
    const ceil = (x, z) => T.ceilOf(T.at(x, z));
    // シャンデリア：天井から金の鎖、二段の輪に灯り
    const chandelier = (x, z, s = 1) => {
      const top = ceil(x, z), y = top - 2.6 * s;
      K.mg('gold', new THREE.CylinderGeometry(0.04, 0.04, top - y, 6), x, (top + y) / 2, z);
      for (const [r0, dy] of [[1.3 * s, 0], [0.8 * s, 0.55 * s]]) {
        const ring = new THREE.TorusGeometry(r0, 0.06, 6, 28); ring.rotateX(Math.PI / 2); K.mg('gold', ring, x, y + dy, z);
        const n = Math.round(r0 * 6);
        for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2; K.mg(K.glow(lit, 2.2), new THREE.CylinderGeometry(0.05, 0.05, 0.2, 6), x + Math.cos(a) * r0, y + dy + 0.16, z + Math.sin(a) * r0); }
      }
      K.mg(K.glow(lit, 1.6), new THREE.SphereGeometry(0.28 * s, 12, 10), x, y - 0.2, z);
      const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex(), color: hdr(lit, 0.5), blending: THREE.AdditiveBlending, depthWrite: false }));
      sp.scale.setScalar(4 * s); sp.position.set(x, y + 0.2, z); K.scene.add(sp);
    };
    // 壁の燭台（ry = 壁の正面）
    const sconce = (x, z, ry) => { const y = K.gy(x, z); K.mg('gold', new THREE.BoxGeometry(0.1, 0.5, 0.3), x, y + 2.6, z, [0, ry, 0]); K.mg(K.glow(lit, 2.2), new THREE.BoxGeometry(0.18, 0.28, 0.18), x + Math.sin(ry) * 0.25, y + 2.95, z + Math.cos(ry) * 0.25); };
    // 額の絵（肖像画）
    const portrait = (x, z, ry, face, y = 3.2) => {
      K.mg('gold', new THREE.BoxGeometry(1.5, 1.9, 0.12), x, K.gy(x, z) + y, z, [0, ry, 0]);
      K.mg(face, new THREE.BoxGeometry(1.2, 1.6, 0.14), x, K.gy(x, z) + y, z, [0, ry, 0]);
      K.mg(happy ? '#ffe0b0' : '#d8d0c8', new THREE.SphereGeometry(0.34, 12, 10), x + Math.sin(ry) * 0.12, K.gy(x, z) + y + 0.1, z + Math.cos(ry) * 0.12, [0, ry, 0], [1, 1, 0.35]);
      K.mg('gold', new THREE.ConeGeometry(0.22, 0.28, 5), x + Math.sin(ry) * 0.1, K.gy(x, z) + y + 0.55, z + Math.cos(ry) * 0.1);
    };
    // 本棚（ry = 正面）：棚板と色とりどりの背表紙
    const shelf = (x, z, ry, w = 3) => {
      const y = K.gy(x, z), c = Math.cos(ry), sn = Math.sin(ry);
      K.box(x, z, w, 3.2, 0.6, 'wood2', { ry });
      for (let k = 0; k < 4; k++) for (let b = 0; b < Math.floor(w / 0.22); b++) {
        if (K.r() < 0.12) continue;
        const u = -w / 2 + 0.2 + b * 0.22, h = 0.45 + K.r() * 0.2;
        K.mg(pick(['#b84a4a', '#4a6ab8', '#4a9a5a', '#c8a040', '#8a5ab8', '#6a4a30']), new THREE.BoxGeometry(0.18, h, 0.42), x + u * c + sn * 0.12, y + 0.3 + k * 0.75 + h / 2, z - u * sn + c * 0.12, [0, ry, 0]);
      }
    };
    // ---- 玉座の間 ----
    K.mesh(new THREE.PlaneGeometry(3.6, 17.6), 'clothRed', 0, 0.03, -3.8, { rx: -Math.PI / 2, noShadow: true });
    for (const x of [-1.9, 1.9]) K.mesh(new THREE.BoxGeometry(0.12, 0.04, 17.6), 'gold', x, 0.04, -3.8, { noShadow: true });
    K.mesh(new THREE.PlaneGeometry(3.6, 4.2), 'clothRed', 0, 0.03, -16.1, { rx: -Math.PI / 2, noShadow: true });
    K.box(0, -19.3, 2.6, 3.0, 1.2, 'gold', { round: true }); K.box(0, -18.8, 2.3, 0.55, 1.7, 'clothRed', { y: 0.25, col: false });
    K.mesh(new THREE.SphereGeometry(0.34, 12, 10), K.glow('#ffd27a', 2), 0, 3.3, -19.7);
    for (const [x, z] of [[-2.2, -17.4], [2.2, -17.4]]) K.cyl(x, z, 0.1, 5, 'gold', { seg: 8 });
    K.box(0, -18.7, 4.8, 0.3, 2.9, happy ? 'clothRed' : 'clothPurple', { y: 5, col: false });
    for (const x of [-2.4, 2.4]) K.mesh(new THREE.PlaneGeometry(1.1, 4.6), K.stdM(clothC, 0.9, { side: THREE.DoubleSide }), x, 2.7, -19.2, { ry: x > 0 ? -0.35 : 0.35, noShadow: true });
    K.banner(0, -19.95, 0, 8.8, 2.2, clothC, '#ffd27a', 1.8);
    K.catStatue(-8.2, -11, 0.3, 1.2, 'gold', '#ffffff'); K.catStatue(8.2, -11, -0.3, 1.2, 'gold', '#ffffff');
    for (const sd of [-1, 1]) for (let z = -10; z <= 2; z += 4) K.column(sd * 9.5, z, T.ceilOf(T.at(sd * 9.5, z)) - 0.1, 0.5, 'marble');
    for (const z of [-12, -2]) chandelier(0, z, 1.1);
    for (const sd of [-1, 1]) for (const z of [-8, 0]) K.banner(sd * 13.95, z, -sd * Math.PI / 2, 6.8, 3.4, clothC);
    for (const sd of [-1, 1]) for (const z of [-4, 3]) sconce(sd * 13.9, z, -sd * Math.PI / 2);
    // ---- 宝物庫：笑いの実の台座（ガラスの覆い）、金貨の山と宝箱 ----
    K.cyl(20, -9, 0.7, 1.2, 'marble', { seg: 12 }); K.mesh(new THREE.CylinderGeometry(0.5, 0.5, 0.1, 16), 'gold', 20, 1.25, -9);
    if (storyCond('scene:c6_04')) { const f = K.mesh(new THREE.SphereGeometry(0.28, 14, 12), K.glow('#ffd24a', 2.6), 20, 1.62, -9); K.tick((dt, t) => { f.position.y = K.gy(20, -9) + 1.62 + Math.sin(t * 2) * 0.05; }); K.light(20, 2.5, -9, '#ffd24a', 5, 8); }
    K.mesh(new THREE.SphereGeometry(0.62, 18, 12, 0, Math.PI * 2, 0, Math.PI / 2), new THREE.MeshStandardMaterial({ color: '#dff4ff', transparent: true, opacity: 0.22, roughness: 0.05, metalness: 0.4, depthWrite: false }), 20, 1.3, -9, { noShadow: true });
    for (const [x, z, s] of [[22.6, -5, 1], [17.6, -13.4, 0.8], [23, -8.5, 0.7]]) { K.mg('gold', new THREE.ConeGeometry(0.9 * s, 0.7 * s, 14), x, 0.35 * s, z); for (let i = 0; i < 6; i++) K.mg('gold', new THREE.CylinderGeometry(0.12, 0.12, 0.03, 10), x + (K.r() - 0.5) * 1.6 * s, 0.02, z + (K.r() - 0.5) * 1.6 * s); }
    K.box(17.6, -5, 1.1, 0.8, 0.7, 'clothRed', { round: true }); K.mesh(new THREE.BoxGeometry(1.14, 0.1, 0.74), 'gold', 17.6, 0.55, -5);
    sconce(23.9, -12, -Math.PI / 2); sconce(16.1, -5, Math.PI / 2);
    // ---- 図書室：本棚、読書机と地球儀 ----
    shelf(-23.6, -10, Math.PI / 2, 3.4); shelf(-23.6, -4.6, Math.PI / 2, 2); shelf(-20, -14.6, 0, 4);
    K.box(-20, -8, 1.4, 0.8, 0.9, 'wood', { round: true });
    K.mesh(new THREE.BoxGeometry(0.5, 0.06, 0.36), '#f4ecd8', -20, 0.84, -8, { ry: 0.3 });
    K.mesh(new THREE.SphereGeometry(0.3, 16, 12), happy ? '#6ab0e8' : '#9aa8b4', -21.6, 1.3, -6); K.cyl(-21.6, -6, 0.1, 1.0, 'wood2', { seg: 6 });
    chandelier(-20, -9, 0.6);
    // ---- 入口の大広間：じゅうたん、歴代の王の肖像画、猫の騎士の像、鉢植え、大シャンデリア ----
    K.mesh(new THREE.PlaneGeometry(3.6, 15.6), 'clothRed', 0, 0.03, 14.2, { rx: -Math.PI / 2, noShadow: true });
    for (const [x, z, ry, col] of [[-13.9, 8.6, Math.PI / 2, '#7a3a4a'], [-13.9, 20, Math.PI / 2, '#3a4a7a'], [13.9, 8.6, -Math.PI / 2, '#3a6a4a'], [13.9, 20, -Math.PI / 2, '#6a4a2a']]) portrait(x, z, ry, happy ? col : '#6a6670');
    for (const [x, z] of [[-10, 20.6], [10, 20.6]]) { K.catStatue(x, z, Math.PI, 1.2, 'stone2'); K.mg('iron', new THREE.CylinderGeometry(0.03, 0.03, 2.6, 5), x + 0.5, K.gy(x, z) + 1.9, z, [0, 0, 0.1]); }
    for (const [x, z] of [[-12.5, 7], [12.5, 7], [-12.5, 21], [12.5, 21]]) { K.cyl(x, z, 0.5, 0.7, 'marble', { seg: 12 }); K.mesh(new THREE.SphereGeometry(0.6, 14, 10), happy ? 'leaf' : 'leafGray', x, 1.15, z); }
    chandelier(0, 12, 1.2);
    for (const sd of [-1, 1]) for (const z of [11.5, 18.5]) sconce(sd * 13.9, z, -sd * Math.PI / 2);
    K.bench(-8, 13, Math.PI / 2); K.bench(8, 13, -Math.PI / 2);
    // ---- 食堂：長い食卓といす、燭台と皿 ----
    K.box(-20, 12, 1.6, 0.8, 8, 'wood', { round: true });
    K.mesh(new THREE.BoxGeometry(1.2, 0.02, 7.6), happy ? 'clothWhite' : '#d8d4d0', -20, 0.82, 12, { noShadow: true });
    for (let z = 9; z <= 15; z += 1.5) for (const sd of [-1, 1]) { K.box(-20 + sd * 1.25, z, 0.55, 0.45, 0.55, 'wood2', { col: false }); K.mesh(new THREE.BoxGeometry(0.55, 0.9, 0.1), 'wood2', -20 + sd * 1.5, 0.9, z, { ry: Math.PI / 2 }); K.mg('white', new THREE.CylinderGeometry(0.2, 0.16, 0.03, 12), -20 + sd * 0.45, K.gy(-20, z) + 0.85, z); }
    for (const z of [10, 14]) { K.mg('gold', new THREE.CylinderGeometry(0.08, 0.12, 0.4, 8), -20, K.gy(-20, z) + 1.02, z); K.mg(K.glow(lit, 2.4), new THREE.SphereGeometry(0.07, 8, 6), -20, K.gy(-20, z) + 1.3, z); }
    chandelier(-20, 12, 0.6);
    // ---- 厨房：かまど、鍋、樽と木箱 ----
    K.box(23.4, 12, 1.2, 1.2, 3, 'stone', { round: true }); K.fire(23.2, 1.25, 11.2, '#ff9a3a', 18, 0.2); K.fire(23.2, 1.25, 12.8, '#ff9a3a', 18, 0.2);
    for (const z of [11.2, 12.8]) K.mesh(new THREE.CylinderGeometry(0.35, 0.3, 0.4, 12), 'iron', 23.2, 1.45, z);
    K.barrel(23, 16.2); K.barrel(23, 17.5); K.crate(21.5, 19.2); K.crate(20.3, 19.3, 0.8);
    K.box(19, 12, 1, 0.85, 2.4, 'wood', { round: true });
    for (let i = 0; i < 3; i++) K.mesh(new THREE.SphereGeometry(0.18, 8, 6), pick(['#ff8a5a', '#8ad85a', '#ffd24a']), 19 + (K.r() - 0.5) * 0.5, 1.0, 11.2 + i * 0.8);
    K.light(0, 6, -8, happy ? '#fff0d8' : '#f0ece8', 8, 24); K.light(0, 5, 14, happy ? '#fff0d8' : '#f0ece8', 7, 20);
  },
  // 笑顔の塔 1F：大ロビーの玉・太鼓・ポスター、切符売り場
  tower(K) {
    const P = (c, r) => K.P(c, r);
    for (const [c, r, col] of [[6, 8, '#ff6a8a'], [15, 8, '#6ad8ff'], [6, 15, '#ffd27a'], [15, 15, '#8aff9a']]) { const [x, z] = P(c, r); K.mesh(new THREE.SphereGeometry(0.6, 16, 12), col, x, 0.6, z); K.col(x, z, 0.6, 1.2); }
    for (const [c, r] of [[8, 19], [13, 19]]) { const [x, z] = P(c, r); K.cyl(x, z, 0.7, 0.9, 'clothRed', { seg: 14 }); K.mesh(new THREE.CylinderGeometry(0.72, 0.72, 0.08, 14), 'white', x, 0.92, z); }
    { const [x, z] = P(3, 2); K.box(x, z, 2.6, 1.1, 1.2, 'wood', { round: true }); K.sign(x, z + 0.7, 0, 'きっぷ売り場', null, '#ffd27a', 1.7, 2); }
    { const [x, z] = P(17, 3); K.crate(x, z); K.crate(x + 1.2, z - 0.2, 0.8); K.barrel(x - 1.4, z + 1); }
    for (const [c, r] of [[5, 7], [16, 7], [5, 16], [16, 16]]) { const [x, z] = P(c, r); K.brazier(x, z, '#ffd27a', 1.1); }
    { const [x, z] = P(10.5, 6.6); K.sign(x, z + 0.3, 0, '大ロビー', '↑ 楽屋・大舞台', '#ffd27a', 4.6, 3); }
    { const [x, z] = P(1, 12); K.paper(x - 0.95, z, Math.PI / 2, '大サーカス！', ['笑顔の塔', '主演：ピエロ'], { bg: '#e8d0d6', ink: '#a0607a', stain: true, w: 1.3 }); }
  },
  // 2F：楽屋の鏡台・衣装かけ・小道具
  tower2f(K) {
    const P = (c, r) => K.P(c, r);
    for (let i = 0; i < 3; i++) { const [x, z] = P(9 + i * 2.5, 7); K.box(x, z, 1.6, 0.8, 0.6, 'wood'); K.mesh(new THREE.PlaneGeometry(1.1, 1.3), K.glow('#fff0f8', 1.2), x, 1.7, z - 0.29, { noShadow: true }); }
    for (const [c, r] of [[14, 1], [17, 1], [2, 15], [19, 15]]) { const [x, z] = P(c, r); K.mesh(new THREE.BoxGeometry(2, 0.08, 0.08), 'metal', x, 1.8, z); for (let i = 0; i < 4; i++) K.mesh(new THREE.BoxGeometry(0.35, 1.1, 0.12), pick(['clothRed', 'clothYellow', 'clothPurple', 'clothPink']), x - 0.75 + i * 0.5, 1.2, z); K.col(x, z, 1, 2); }
    for (const [c, r, col] of [[13, 9, '#ff6a8a'], [4, 18, '#6ad8ff'], [17, 18, '#ffd27a']]) { const [x, z] = P(c, r); K.mesh(new THREE.SphereGeometry(0.45, 14, 10), col, x, 0.45, z); K.col(x, z, 0.45, 0.9); }
    for (const [c, r] of [[2, 12], [19, 12], [9, 20], [14, 20]]) { const [x, z] = P(c, r); K.brazier(x, z, '#ffd27a', 1.0); }
  },
  // 3F：空中ブランコ（ゆれる）と、吹き抜けの底の光、まん中の舞台の輪
  tower3f(K) {
    const P = (c, r) => K.P(c, r);
    for (const [c, r] of [[10.5, 6], [7, 16], [15, 5]]) {
      const [x, z] = P(c, r), g = new THREE.Group(); g.position.set(x, 9, z); K.scene.add(g);
      for (const sd of [-1, 1]) { const rope = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 5, 5), K.mat('clothYellow')); rope.position.set(sd * 0.8, -2.5, 0); g.add(rope); }
      const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 1.8, 8), K.mat('gold')); bar.rotation.z = Math.PI / 2; bar.position.y = -5; g.add(bar);
      const ph = K.r() * 6; K.tick((dt, t) => { g.rotation.x = Math.sin(t * 1.1 + ph) * 0.5; });
    }
    { const [x, z] = P(10.5, 11.5); K.mesh(new THREE.RingGeometry(3.6, 3.9, 48), K.glow('#ffd27a', 1.8), x, 0.03, z, { rx: -Math.PI / 2, noShadow: true }); }
    K.v.emitters.push(dt => { if (Math.random() < dt * 10) { const [x, z] = P(3 + Math.random() * 16, 4 + Math.random() * 14); K.v.p.emit(V3(x, -8, z), V3(0, 3, 0), hdr(pick(['#ff9ad8', '#ffd27a', '#8ad8ff']), 1.8), { life: 3, size: 0.12, drag: 0 }); } });
    for (const [c, r] of [[3, 2], [18, 2], [3, 20], [18, 20]]) { const [x, z] = P(c, r); K.brazier(x, z, '#ffd27a', 1.1); }
  },
  // 最上階：幕と舞台、客席のベンチ、スポットライト
  towerTop(K) {
    const P = (c, r) => K.P(c, r);
    const [sx, sz] = P(10.5, 1), y1 = K.gy(sx, sz);
    for (const s of [-1, 1]) K.mesh(new THREE.PlaneGeometry(9, 8), 'clothRed', sx + s * 8, y1 + 4, sz - 0.9, { noShadow: true }).material.side = THREE.DoubleSide;
    K.mesh(new THREE.PlaneGeometry(26, 1.4), 'clothYellow', sx, y1 + 7.4, sz - 0.8, { noShadow: true });
    for (let i = 0; i < 4; i++) { const x = sx - 7.5 + i * 5; K.mesh(new THREE.ConeGeometry(1.2, 6, 16, 1, true), new THREE.MeshBasicMaterial({ color: hdr('#fff0c8', 0.6), transparent: true, opacity: 0.12, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }), x, 3, sz + 5, { noShadow: true }); }
    // 客席（通路を残して並ぶベンチ）
    for (let r = 10; r <= 15; r += 1.5) for (const c of [5, 8, 13, 16]) { const [x, z] = P(c, r); K.box(x, z, 3.4, 0.5, 0.7, 'clothPurple'); }
    for (const [c, r] of [[4, 9], [17, 9], [4, 17], [17, 17]]) { const [x, z] = P(c, r); K.brazier(x, z, '#ffd27a', 1.1); }
    for (const [c, r, col] of [[2, 4, '#ff6a8a'], [19, 4, '#6ad8ff']]) { const [x, z] = P(c, r); K.mesh(new THREE.SphereGeometry(0.5, 14, 10), col, x, 0.5, z); }
    K.light(sx, y1 + 6, sz + 6, '#ffd8f0', 10, 22);
  },

  // ---------------- 第四章 ----------------
  // くろねこ谷：墓標の丘、古いテント、谷の集落、川と二つの橋
  valley(K) {
    K.cragTop({ trees: [['dead', 2], ['round', 1]], leaf: ['#6a6a7a', '#7a6a8a'], density: 0.3, rock: '#6a6070' });
    // 墓標：ハヤテ・リン・ゴロウ、名のない四つ目
    K.mesh(new THREE.SphereGeometry(5, 20, 12, 0, Math.PI * 2, 0, Math.PI / 2), 'grass', -15, -0.8, -16.5, { noShadow: true }).scale.y = 0.25;
    [['ハヤテ', -19], ['リン', -16.5], ['ゴロウ', -14], [null, -11.5]].forEach(([n, x]) => K.grave(x, -16, 0, n, '#ffffff'));
    K.deadTree(-22, -19, 1.2); K.flowers(-15, -13, 12, 2, ['#c8a8ff', '#ffffff']);
    // 影の四剣の古いテント（川の北の野営あと）
    K.tent(18, -9, 0.3, 'clothPurple'); K.campfire(15, -7);
    // 谷の集落への道（東の出入口）
    K.signpost(28, 15.5, -0.6, '→ 谷の集落', '宿と長老の家', '#c8a8ff');
    for (const [x, z] of [[22, 24], [8, 28]]) K.lantern(x, z, '#c8a8ff');
    K.signpost(-24, 2, 0.3, '→ 谷の集落', '↑ 墓標の丘・黒影洞窟');
    for (const [x, z] of [[-30, -4], [0, 30], [30, -12]]) K.rock(x, z, 0.8 + K.r() * 0.5, 'rockDark');
  },
  // 谷の集落：宿、長老クロネ婆の家（見晴らし台）、民家、井戸、洗濯物、紫の灯り、たき火
  valleyVillage(K) {
    K.cragTop({ trees: [['dead', 1.5], ['round', 1]], leaf: ['#6a6a7a', '#7a6a8a'], density: 0.35, rock: '#6a6070' });
    K.catHouse(-12, -11, 7, 5, 3.6, 's', { roof: 'roofGray', sign: '谷の宿', sub: 'ゆっくり おやすみ', signCol: '#c8a8ff', lit: true, smoke: true });
    K.catHouse(12, -15, 6, 5, 3.4, 's', { roof: 'roofPurple', sign: '長老の家', signCol: '#c8a8ff', lit: true, smoke: true });
    K.catHouse(14, 10, 6, 5, 3.4, 'n', { roof: 'roofPurple', lit: true });
    K.catHouse(5, 11.5, 5, 4.6, 3.2, 'n', { roof: 'roofGray' });
    K.catHouse(-14.5, 11.6, 5, 4.4, 3.2, 'n', { roof: 'roofPurple', lit: true });
    K.well(7, -3);
    for (const [x, z] of [[-6, -4], [-6, 5], [2.5, -3], [2.5, 6], [12, 4], [17.2, -11], [-17, 8]]) K.lantern(x, z, '#c8a8ff');
    // 洗濯物のひも
    for (const [x0, z0, x1, z1] of [[12.5, -4, 18, -5.5], [-18, 5.2, -12, 5.2]]) K.bunting(x0, z0, x1, z1, ['#f4f0fa', '#c8b8e8', '#fff8f0', '#b8c8e0'], 2.4);
    K.campfire(-6, 13); K.bench(-8.6, 13, Math.PI / 2); K.bench(-3.4, 13, -Math.PI / 2);
    K.barrel(-17, -8); K.barrel(-16.2, -6.8); K.crate(-7.5, -8.5);
    K.flowers(-12, -4, 10, 1.6, ['#c8a8ff', '#ffffff']); K.flowers(16, -2, 12, 2, ['#c8a8ff', '#ffffff']); K.flowers(10, -14, 8, 1.4, ['#c8a8ff', '#ffffff']);
    for (const [x, z] of [[18, 14], [-18, -12], [8, -8]]) K.rock(x, z, 0.7 + K.r() * 0.4, 'rockDark');
  },
  // 黒影洞窟 B1：紫の水晶、石筍、地底の泉、焚き火のあと、影の壁と光の水晶
  cave(K) {
    for (const [x, z, n] of [[-55, -45, 4], [-27, -45, 3], [-53, 27, 4], [-33, 43, 3], [31, 11, 3], [53, 45, 4], [27, -45, 4], [55, -23, 3], [-19, -7, 3], [19, -7, 3], [-13, 31, 3], [13, 31, 3]]) K.ore(x, z, n, '#a07bff', 1);
    for (const [x, z] of [[-14, 0], [14, 4], [-6, 10], [10, -4], [-10, 36], [10, 44], [40, 40], [34, 22], [35, -30], [47, -24], [-40, -35], [-45, 35], [-8, 26], [-50, 2]]) K.stalag(x, z, 1.8 + K.r() * 1.6);
    K.scratches(-53.97, -11, Math.PI / 2);
    // 焚き火のあと：石の輪と焦げた薪（火は消えている）
    for (let i = 0; i < 7; i++) { const a = i / 7 * Math.PI * 2; K.mesh(new THREE.DodecahedronGeometry(0.22, 0), 'rockDark', -50 + Math.cos(a) * 0.6, 0.12, -14 + Math.sin(a) * 0.6); }
    for (let i = 0; i < 3; i++) K.mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.9, 6), '#2a2220', -50, 0.1, -14, { rz: Math.PI / 2, ry: i * 1.05 });
    K.v.emitters.push(dt => { if (Math.random() < dt * 5) K.v.p.emit(V3(-46 + (Math.random() - 0.5) * 5, K.gy(-46, -41) - 0.3, -41 + (Math.random() - 0.5) * 4), V3(0, 0.6, 0), hdr('#8a9aff', 2), { life: 2.4, size: 0.07, drag: 0 }); });
    K.seals(); K.rubbles();
    K.light(-46, 3, -41, '#6a8aff', 7, 16); K.light(2, 4, -20, '#a07bff', 7, 18); K.light(0, 4, 39, '#a07bff', 7, 20); K.light(45, 4, -36, '#b89aff', 6, 18);
  },
  // 黒影洞窟 B2：地底湖。湖面の光、岸のゴロウの盾とリンのリボン、橋のたもとの影の壁、東の岩棚の落石
  caveLake(K) {
    for (const [x, z, n] of [[-45, -39, 4], [33, -39, 3], [-29, -39, 3], [53, -15, 4], [-49, 45, 3], [49, 43, 3], [-15, 45, 3], [15, 45, 3]]) K.ore(x, z, n, '#a07bff', 1);
    for (const [x, z] of [[-35, 12], [35, 12], [-20, 21], [20, 21], [38, 19], [-25, -40], [25, -40], [45, 39], [-40, 40]]) K.stalag(x, z, 1.8 + K.r() * 1.8);
    // 岸に打ち上げられた、ゴロウの割れた盾とリンのリボン
    K.mesh(new THREE.CylinderGeometry(0.75, 0.75, 0.12, 20, 1, false, 0, Math.PI), '#8a7a6a', -13.4, 0.3, 13, { rx: 1.2, rz: 0.3 });
    K.mesh(new THREE.CylinderGeometry(0.75, 0.75, 0.12, 20, 1, false, Math.PI + 0.3, Math.PI - 0.3), '#8a7a6a', -13, 0.12, 13.4, { rx: 1.45, rz: -0.2 });
    K.mesh(new THREE.TorusGeometry(0.16, 0.05, 6, 14), '#5a8ad8', -12.2, 0.08, 11.8, { rx: Math.PI / 2 });
    K.mesh(new THREE.BoxGeometry(0.5, 0.02, 0.1), '#5a8ad8', -12, 0.06, 12.1, { ry: 0.6 });
    K.mesh(new THREE.OctahedronGeometry(0.08), K.glow('#cfefff', 2.4), -12.2, 0.2, 11.8, { noShadow: true });
    K.v.emitters.push(dt => { if (Math.random() < dt * 14) K.v.p.emit(V3((Math.random() - 0.5) * 80, -0.3, -11 + (Math.random() - 0.5) * 34), V3(0, 0.7, 0), hdr('#8a6aff', 2.2), { life: 2.5, size: 0.08, drag: 0 }); });
    K.seals(); K.rubbles();
    K.light(0, 6, -10, '#8a6aff', 10, 40); K.light(0, 5, 43, '#a07bff', 6, 16); K.light(-45, 4, -35, '#6a8aff', 6, 16); K.light(51, 5, -20, '#b89aff', 6, 16);
  },
  // 黒影洞窟 B3：闇の淵（底から立ちのぼる闇のもや）、記憶のかけら、闇の扉、三本の剣の大広間と岩の列柱
  caveDeep(K) {
    for (const [x, z, n] of [[-43, -15, 4], [-43, 25, 3], [-9, -15, 3], [43, -15, 4], [43, 29, 3], [45, 39, 3], [-25, -39, 5], [25, -39, 5], [-25, -27, 3], [25, -27, 3], [-35, 39, 3], [15, 39, 3]]) K.ore(x, z, n, '#a07bff', 1);
    for (const [x, z] of [[-40, 21], [-40, -9], [-24, -13], [30, -13], [41, 1], [41, 21], [-20, 37]]) K.stalag(x, z, 1.8 + K.r() * 1.6);
    for (const sd of [-1, 1]) for (const z of [-38, -32, -27]) K.column(sd * 15, z, 7, 0.6, 'darkStone');
    for (let i = 0; i < 3; i++) { const x = -1.2 + i * 1.2, z = -39.2 - (i === 1 ? 0.4 : 0); K.mesh(new THREE.BoxGeometry(0.08, 1.2, 0.02), 'metal', x, 0.5, z, { rz: (i - 1) * 0.12 }); K.mesh(new THREE.BoxGeometry(0.34, 0.06, 0.06), 'gold', x, 0.95, z, { rz: (i - 1) * 0.12 }); }
    K.mesh(new THREE.CircleGeometry(2.2, 24), K.glow('#8a6aff', 0.6), 0, 0.03, -39.4, { rx: -Math.PI / 2, noShadow: true });
    K.v.emitters.push(dt => {
      if (Math.random() < dt * 6) K.v.p.emit(V3((Math.random() - 0.5) * 4, 0.2, -39.4 + (Math.random() - 0.5) * 2), V3(0, 0.8, 0), hdr('#b89aff', 2), { life: 2.4, size: 0.07, drag: 0 });
      // 闇の淵の底から立ちのぼる、闇のもやと小さな光
      if (Math.random() < dt * 22) K.v.p.emit(V3((Math.random() - 0.5) * 50, -6 - Math.random() * 6, 12 + (Math.random() - 0.5) * 34), V3(0, 2.2 + Math.random(), 0), hdr(Math.random() < 0.7 ? '#3a1a6a' : '#b89aff', 1.6), { life: 4, size: 0.18, drag: 0.1 });
    });
    K.seals();
    K.light(0, 5, 30, '#8a6aff', 7, 22); K.light(1, 3, 6, '#ffe2a8', 5, 12); K.light(0, 4, -34, '#a07bff', 8, 20); K.light(2, 3, -17, '#6a8aff', 5, 12);
  },

  // ---------------- 第五章 ----------------
  // 古代遺跡・外庭：倒れた柱、四匹の猫の像、大階段の上の遺跡の入口
  ruinsOut(K) {
    K.flora({ trees: [['round', 3], ['pine', 1]], leaf: ['#5a9a4a', '#6aa858', '#4a8a44'], bush: 0.7, rocks: 0.4, rock: '#b0a890' });
    // 入口の門構え（北の高台）
    for (const x of [-5, 5]) K.column(x, -31, 8, 0.8, 'stone');
    K.box(0, -31, 13, 1.4, 2.2, 'stone2', { y: 8, col: false });
    K.catStatue(-8, -28, 0.3, 1.4, 'stone', '#8affe0'); K.catStatue(8, -28, -0.3, 1.4, 'stone', '#8affe0');
    // 四匹の猫の像
    for (let i = 0; i < 4; i++) K.catStatue(7 + i * 1.3, 12, Math.PI + (i - 1.5) * 0.2, i === 3 ? 0.7 : 1, 'stone');
    // 崩れた柱（道ばたと、木立の中）
    for (const [x, z, h, f] of [[-16, 6, 4, false], [14, 0, 5, false], [20, 20, 3, true], [-18, 30, 2.5, false], [22, -26, 3, false], [28, -18, 4, false], [30, 24, 2, true], [-9, -20, 2, false], [9, -20, 2, false]]) K.pillarBroken(x, z, h, f);
    for (const [x, z] of [[-26, -4], [-30, -8]]) K.flowers(x, z, 10, 1.6, ['#ffffff', '#b8ffe8']);
    K.flowers(-4, 26, 12, 2);
  },
  // 壁画の回廊：壁画、柱、光る輪の道、奥に封印の扉
  ruinsIn(K) {
    K.mural(-13.8, 10, Math.PI / 2, 0); K.mural(15.8, -4, -Math.PI / 2, 1); K.mural(-15.8, -18, Math.PI / 2, 2);
    for (let z = 5; z <= 17; z += 6) for (const x of [-8, 8]) K.column(x, z, 7, 0.6, 'stone');
    for (const z of [-34, -24]) for (const x of [-8, 8]) K.column(x, z, 7, 0.6, 'stone');
    const open = storyCond('scene:c5_03');
    const d = K.sealDoor(0, -37.2, 0, open);
    if (open) d.d.visible = false;
    for (let i = 0; i < 8; i++) K.mesh(new THREE.RingGeometry(0.5, 0.6, 24), K.glow('#8affe0', 1.2), 0, 0.03, 36 - i * 4.5, { rx: -Math.PI / 2, noShadow: true });
    // 地下墓所の石の棺と、宝物庫の台座
    for (const x of [-9, -3]) K.box(x, -18, 1.4, 0.8, 2.6, 'stone2');
    K.box(3, -4, 1.2, 1, 1.2, 'stone2'); K.mesh(new THREE.OctahedronGeometry(0.3), K.glow('#8affe0', 2.4), 3, 1.4, -4);
    for (const [x, z] of [[-6, 30], [6, 30], [-6, -30], [6, -30]]) K.brazier(x, z, '#8affe0', 1.2);
  },

  // 封印の間：樹の根をかたどった祭壇と、床に広がる光る根
  ruinsSeal(K) {
    K.box(0, -9, 3.4, 1.2, 2.2, 'stone2', { round: true });
    const gem = K.mesh(new THREE.OctahedronGeometry(0.5), K.glow('#8affe0', 2.4), 0, 2.1, -9);
    K.tick((dt, t) => { gem.rotation.y += dt * 0.5; gem.position.y = 2.1 + Math.sin(t * 1.5) * 0.08; });
    for (let i = 0; i < 7; i++) { const a = Math.PI * (0.15 + i * 0.7 / 6), len = 5 + (i % 3) * 1.5; K.mesh(new THREE.BoxGeometry(0.16, 0.04, len), K.glow('#8affe0', 1.2), Math.cos(a) * (len / 2 + 1.2), 0.03, -9 + Math.sin(a) * (len / 2 + 1.2), { ry: Math.PI / 2 - a, noShadow: true }); }
    for (const z of [-6, 2]) for (const x of [-7, 7]) K.column(x, z, 7, 0.6, 'stone');
    for (const x of [-4, 4]) K.brazier(x, 6, '#8affe0', 1.2);
    K.light(0, 5, -8, '#8affe0', 6, 14);
  },

  // ---------------- 第六章 ----------------
  // 魔王領：猫じゃらしの野原、健康診断のテント、有給の立て看板、北の高台に魔王城の門
  demonLand(K) {
    K.cragTop({ trees: [['spooky', 1]], density: 0.25, rock: '#5a4a70' });
    K.tent(-16, 18, 0.4, 'clothWhite'); K.sign(-16, 20.2, 0.4, '健康診断', '順番にお並びください', '#ff8ad8', 2.6, 2.6);
    for (let i = 0; i < 3; i++) K.box(-12 + i * 1.3, 10.5, 0.5, 0.45, 0.5, 'wood', { col: false });
    K.signpost(14, 24, -0.3, '有給休暇 申請受付中', '※魔王さまの遊び相手になれる方に限る');
    for (let i = 0; i < 40; i++) K.nekojarashi(8 + K.r() * 18, -22 + K.r() * 14, 0.8 + K.r() * 0.6);
    for (let i = 0; i < 12; i++) K.nekojarashi(-18 + K.r() * 10, -12 + K.r() * 6, 0.8 + K.r() * 0.5);
    // 城門（北の高台）
    for (const x of [-5, 5]) { K.box(x, -36, 2.4, 9, 2.4, 'purpleStone'); K.mesh(new THREE.ConeGeometry(1.8, 3, 6), 'darkStone', x, 10.5, -36); }
    K.mesh(new THREE.BoxGeometry(0.8, 1.2, 0.1), K.glow('#ffcf4a', 2), -5, 6, -34.7, { noShadow: true });
    for (const [x, z] of [[-6, -26], [6, -26]]) K.brazier(x, z, '#ff8ad8', 1.3);
    for (const [x, z] of [[-28, 18], [24, 30], [30, -2]]) K.rock(x, z, 0.9, 'purpleStone');
  },
  // 魔王城 1F：じゅうたん、健康診断のベッドと体重計、休憩室のお茶のテーブル、柱の間
  demonCastle(K) {
    const P = (c, r) => K.P(c, r);
    { const [x0, z0] = P(11.5, 22.5), [x1, z1] = P(11.5, 1); K.mesh(new THREE.PlaneGeometry(3.6, Math.abs(z1 - z0)), 'clothRed', x0, 0.03, (z0 + z1) / 2, { rx: -Math.PI / 2, noShadow: true }); }
    for (const [c, r] of [[1.5, 12.5], [1.5, 17]]) { const [x, z] = P(c, r); K.box(x, z, 1.2, 0.7, 2.2, 'clothWhite', { round: true }); }
    { const [x, z] = P(3.5, 18); K.box(x, z, 1, 0.12, 1, 'metal'); K.box(x - 0.4, z, 0.1, 1.2, 0.1, 'metal', { y: 0.1, col: false }); }
    { const [x, z] = P(20.5, 17); K.cyl(x, z, 1, 0.8, 'wood', { seg: 14 }); for (let i = 0; i < 4; i++) { const a = i / 4 * Math.PI * 2; K.box(x + Math.cos(a) * 1.6, z + Math.sin(a) * 1.6, 0.6, 0.5, 0.6, 'clothPurple', { round: true }); } }
    for (const r of [4, 7]) for (const c of [8.5, 14.5]) { const [x, z] = P(c, r); K.column(x, z, 8, 0.6, 'purpleStone'); }
    for (const [c, r] of [[4.5, 1.5], [4.5, 3]]) { const [x, z] = P(c, r); K.crate(x, z); }
    for (let i = 0; i < 3; i++) { const [x, z] = P(19 + i * 1.5, 1.2); K.box(x, z, 1.2, 2.6, 0.5, 'wood2'); }
    for (const [c, r] of [[7, 12], [16, 12], [7, 19], [16, 19]]) { const [x, z] = P(c, r); K.brazier(x, z, '#ff8ad8', 1.2); }
    { const [x, z] = P(10, 22); K.paper(x - 0.95, z, Math.PI / 2, '本日の予定', ['健康診断（全員）', '魔王さまの遊び相手', '（募集中）'], { bg: '#f0e6f4', ink: '#5a3a7a', w: 1.3 }); }
  },
  // 魔王城 2F：吹き抜けの底の光、おもちゃ部屋、没収品の倉庫、壁の旗
  demonCastle2f(K) {
    const P = (c, r) => K.P(c, r);
    K.v.emitters.push(dt => { if (Math.random() < dt * 10) { const [x, z] = P(5 + Math.random() * 14, 9 + Math.random() * 5); K.v.p.emit(V3(x, -10, z), V3(0, 3.5, 0), hdr('#ff8ad8', 2), { life: 3, size: 0.12, drag: 0 }); } });
    for (const [c, r, col] of [[6, 5.5, '#ff6a8a'], [8, 7, '#6ad8ff'], [5.5, 7.5, '#ffd27a']]) { const [x, z] = P(c, r); K.mesh(new THREE.SphereGeometry(0.4, 12, 10), col, x, 0.4, z); }
    for (let i = 0; i < 6; i++) { const [x, z] = P(6 + K.r() * 3, 15.5 + K.r() * 2); K.nekojarashi(x, z, 0.7); }
    { const [x, z] = P(8, 16); K.crate(x, z); K.crate(x, z + 1.2, 0.8); }
    for (const [c, r] of [[2.5, 2.5], [20.5, 2.5], [2.5, 19.5], [20.5, 19.5]]) { const [x, z] = P(c, r); K.brazier(x, z, '#ff8ad8', 1.2); }
    for (const c of [6, 10, 13, 17]) { const [x, z] = P(c, 1.9); K.mesh(new THREE.PlaneGeometry(1.4, 3), 'clothPurple', x, 4, z - 0.85, { noShadow: true }); }
  },
  // 魔王城 3F：大きなクッションの玉座と、猫じゃらし・毛糸玉、光る柱
  demonThrone(K) {
    const P = (c, r) => K.P(c, r);
    { const [x0, z0] = P(11.5, 22.5), [x1, z1] = P(11.5, 3); K.mesh(new THREE.PlaneGeometry(3.6, Math.abs(z1 - z0)), 'clothRed', x0, 0.03, (z0 + z1) / 2, { rx: -Math.PI / 2, noShadow: true }); }
    const [tx, tz] = P(11.5, 1.5);
    K.box(tx, tz, 4, 1.2, 2.4, 'clothPurple', { round: true }); K.box(tx, tz - 1, 4, 3.4, 0.8, 'gold', { round: true });
    for (const [c, r, col] of [[7, 4, '#ff6a8a'], [16, 3, '#6ad8ff'], [9, 6, '#ffd27a']]) { const [x, z] = P(c, r); K.mesh(new THREE.SphereGeometry(0.4, 12, 10), col, x, 0.4, z); }
    for (let i = 0; i < 6; i++) { const [x, z] = P(3 + i * 3.5, 0.9); K.box(x, z, 0.8, 5, 0.8, 'purpleStone', { col: false }); K.mesh(new THREE.OctahedronGeometry(0.3), K.glow('#ff8ad8', 2.4), x, 5.6, z); }
    for (const r of [13, 17]) for (const c of [8, 15]) { const [x, z] = P(c, r); K.column(x, z, 8, 0.55, 'purpleStone'); }
    K.light(tx, 5, tz + 4, '#ff8ad8', 10, 20);
  },

  // ---------------- 第七章 ----------------
  // にゃんだーの樹・根もと：南にそびえる幹、根のアーチ、色あせた葉の木立
  treeRoot(K) {
    const h = treeHealth(), revived = h >= 1;
    const lc = t => '#' + new THREE.Color('#9a9a88').lerp(new THREE.Color(t), h).getHexString();
    K.flora({ trees: [['round', 3], ['dead', 1.2 - h]], leaf: [lc('#5ad06a'), lc('#6abf52'), lc('#4a9a3e')], bush: 0.7, rocks: 0.4 });
    // 幹（区画の外の南にそびえる）
    K.cyl(0, 62, 22, 90, 'bark', { r2: 14, seg: 24, col: false });
    const leaf = new THREE.MeshStandardMaterial({ color: new THREE.Color('#9a9a88').lerp(new THREE.Color('#5ad06a'), h), roughness: 0.9 });
    for (let i = 0; i < 12; i++) { const a = i / 12 * Math.PI * 2; K.mesh(new THREE.IcosahedronGeometry(18, 1), leaf, Math.cos(a) * 30, 80 + (i % 3) * 8, 62 + Math.sin(a) * 26, { noShadow: true }); }
    // 幹から張り出す根（南の根のトンネルの上をまたぐ）
    for (const sd of [-1, 1]) { K.root(sd * 18, 44, sd * 30, 26, 1.8, 10); K.root(sd * 14, 46, sd * 38, 34, 1.5, 8); }
    K.root(-8, 36, 8, 40, 1.4, 7); K.root(-30, 20, -10, 28, 1.2, 4); K.root(30, 22, 12, 34, 1.1, 4);
    for (let i = 0; i < 40; i++) K.mesh(new THREE.CircleGeometry(0.4, 6), revived ? 'leaf' : 'leafGray', (K.r() - 0.5) * 50, 0.04, -16 + (K.r() - 0.5) * 30, { rx: -Math.PI / 2, noShadow: true });
    if (revived) for (let i = 0; i < 24; i++) { const a = K.r() * 6; K.mesh(new THREE.SphereGeometry(1, 10, 8), K.glow(pick(['#ffd24a', '#ff8ab8', '#8ad8ff', '#b8ff8a']), 2), Math.cos(a) * 26, 64 + K.r() * 20, 50 + Math.sin(a) * 20, { noShadow: true }); }
    K.signpost(-3, -24, 0.2, '↓ にゃんだーの樹', '→ 世界の果て');
    // 灰色に色あせた葉の吹きだまり（調べられる）
    for (let i = 0; i < 16; i++) { const a = K.r() * Math.PI * 2, d = Math.sqrt(K.r()) * 1.3; K.mesh(new THREE.CircleGeometry(0.35, 6), 'leafGray', -10 + Math.cos(a) * d, 0.05 + i * 0.004, 10 + Math.sin(a) * d, { rx: -Math.PI / 2, rz: K.r() * 3, noShadow: true }); }
    // 世界の果てへのびる、いちばん太い根（東の小道の南の縁を這う）
    K.mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3([V3(8, -0.6, 19), V3(16, 0.3, 16.4), V3(28, 0.2, 16.5), V3(42, -0.2, 16.4)]), 32, 0.7, 8, false), rootMat(), 0, 0, 0, { abs: true });
  },
  // 樹の地下：根の洞窟。天井をはう根、光るきのこ、東の地底の泉、奥に樹の心臓
  treeUnder(K) {
    const arc = (x0, z0, x1, z1, r, top) => { const y = K.gy((x0 + x1) / 2, (z0 + z1) / 2); const m = K.mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3([V3(x0, y - 0.5, z0), V3((x0 + x1) / 2, y + top, (z0 + z1) / 2), V3(x1, y - 0.5, z1)]), 16, r, 8, false), 'bark', 0, 0, 0, { abs: true }); return m; };
    for (const z of [-12, -8]) arc(-15, z, 15, z + 2, 0.9 + K.r() * 0.4, 5.5);
    for (const z of [18, 26]) arc(-17, z, 17, z + 2, 1 + K.r() * 0.4, 5.5);
    const heart = K.mesh(new THREE.IcosahedronGeometry(2.4, 1), new THREE.MeshStandardMaterial({ color: '#3a4a2a', emissive: '#8aff6a', emissiveIntensity: treeHealth() >= 1 ? 1.4 : 0.35, flatShading: true }), 0, 3.4, 36);
    K.tick((dt, t) => { heart.rotation.y += dt * 0.2; heart.scale.setScalar(1 + Math.sin(t * 1.2) * 0.04); });
    K.col(0, 36, 2.6, 6);
    for (const [x, z] of [[-10, -24], [10, -8], [-8, 8], [9, 22], [-20, -14], [-19, 18]]) K.mushroom(x, z, 1.2, null, '#b8ff8a');
    K.v.emitters.push(dt => { if (Math.random() < dt * 6) K.v.p.emit(V3(19 + (Math.random() - 0.5) * 3, K.gy(19, -20) - 0.3, -20 + (Math.random() - 0.5) * 3), V3(0, 0.6, 0), hdr('#8aff8a', 2), { life: 2.4, size: 0.07, drag: 0 }); });
    K.light(0, 4, 32, '#8aff8a', 10, 20); K.light(0, 8, -24, '#b8ff8a', 6, 18);
    // 西の高台の壁を伝う、光る樹液（調べられる）
    for (const [dz, h] of [[-0.25, 3.0], [0.2, 2.2]]) K.mesh(new THREE.BoxGeometry(0.6, h, 0.16), K.glow('#b8ff8a', 1.6), -21.97, 3.4 - h / 2, dz, { noShadow: true });
    K.mesh(new THREE.CircleGeometry(0.6, 16), K.glow('#b8ff8a', 1.2), -21.3, 0.03, 0, { rx: -Math.PI / 2, noShadow: true });
  },

  // ---------------- 第八章 ----------------
  // 世界の果て：奈落に浮かぶ石の道、浮かぶ岩、果ての闘技場
  worldEnd(K) {
    K.mesh(new THREE.RingGeometry(8, 8.3, 64), K.glow('#b8a8ff', 2), 0, 0.05, -30, { rx: -Math.PI / 2, noShadow: true });
    K.mesh(new THREE.RingGeometry(5, 5.15, 64), K.glow('#ff8ab8', 2), 0, 0.05, -30, { rx: -Math.PI / 2, noShadow: true });
    for (let i = 0; i < 8; i++) { const a = i / 8 * Math.PI * 2 + Math.PI / 8; if (Math.sin(a) > 0.8) continue; K.pillarBroken(Math.cos(a) * 12, -30 + Math.sin(a) * 9, 2 + K.r() * 4, false, 'darkStone'); }
    for (let i = 0; i < 18; i++) K.floatRock((K.r() - 0.5) * 70, (K.r() - 0.5) * 90, -2 + K.r() * 16, 0.8 + K.r() * 2);
    // 樹の根：南の入口から果ての闘技場まで、石の道の下を這って支えている（細い道ではすぐ脇に見える）
    K.mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3([V3(0, -2, 50), V3(-4, -3.5, 40), V3(-4.8, -0.9, 30), V3(-7, -4.5, 20), V3(-6.6, -0.9, 2), V3(-7, -4.5, -8), V3(-4.8, -0.9, -18), V3(-5, -5, -30), V3(0, -9, -46)]), 96, 1.1, 10, false), rootMat(0.6), 0, 0, 0, { abs: true, noShadow: true });
    // 道しるべの石と、奈落から立ちのぼる光
    for (const [x, z] of [[-4, 36], [4, 36], [-6, 10], [6, 10]]) K.pillarBroken(x, z, 1.4 + K.r(), false, 'darkStone');
    K.v.emitters.push(dt => { if (Math.random() < dt * 14) K.v.p.emit(V3((Math.random() - 0.5) * 70, -12, (Math.random() - 0.5) * 90), V3(0, 4, 0), hdr(pick(['#b8a8ff', '#ff8ab8']), 1.6), { life: 4, size: 0.12, drag: 0 }); });
  },

  // ---------------- クリア後 ----------------
  // ねこ神の夢：お菓子の木立、空に浮かぶ魚、奥の段の上に巨大な座布団の玉座
  dream(K) {
    K.flora({ trees: [['candy', 3], ['round', 1]], leaf: ['#ffb8d8', '#b8e0ff', '#fff0a8', '#c8ffc8'], bark: '#fff8ec', bush: 0.7, bushLeaf: ['#ffd8ec', '#d8f0ff'], flower: ['#ffffff', '#ffe07a'] });
    K.box(0, -30, 8, 1.4, 5, 'candyPink', { round: true }); K.box(0, -31.8, 8, 4, 1.4, 'candyYellow', { round: true, y: 1.4 });
    for (const [x, z] of [[-4, -28], [4, -28]]) K.mesh(new THREE.SphereGeometry(0.3, 10, 8), 'gold', x, 1.6, z);
    for (let i = 0; i < 10; i++) {
      const g = new THREE.Group(); const f = new THREE.Mesh(new THREE.SphereGeometry(0.6, 12, 10), toon(pick(['#8ad8ff', '#ff9ab8', '#ffd27a']))); f.scale.set(0.6, 0.8, 1.8); g.add(f);
      const t = new THREE.Mesh(new THREE.ConeGeometry(0.4, 0.6, 3), f.material); t.rotation.x = Math.PI / 2; t.position.z = -1.1; t.scale.x = 0.3; g.add(t);
      const x = (K.r() - 0.5) * 50, z = (K.r() - 0.5) * 50, y0 = 4 + K.r() * 6, ph = K.r() * 6; g.position.set(x, y0, z); K.scene.add(g);
      K.tick((dt, tt) => { g.position.y = y0 + Math.sin(tt * 0.8 + ph) * 1; g.rotation.y = tt * 0.3 + ph; });
    }
    for (const [x, z] of [[-24, -22], [24, -22], [-24, 16], [20, 17]]) K.candy(x, z, 0.8);
  },
};
delete ZONE_BUILD._unused;
